            chatInfoValueSize: clampInt(raw.chatInfoValueSize ?? d.chatInfoValueSize, 11, 20, d.chatInfoValueSize),
            chatInfoGroupGap: clampInt(raw.chatInfoGroupGap ?? d.chatInfoGroupGap, 8, 20, d.chatInfoGroupGap),
