            cardBubbleRadius: clampInt(raw.cardBubbleRadius ?? d.cardBubbleRadius, 4, 24, d.cardBubbleRadius),
            cardVisualHeight: clampInt(raw.cardVisualHeight ?? d.cardVisualHeight, 72, 180, d.cardVisualHeight),
            cardDescFontSize: clampInt(raw.cardDescFontSize ?? d.cardDescFontSize, 11, 20, d.cardDescFontSize),
            momentsCoverHeight: clampInt(raw.momentsCoverHeight ?? d.momentsCoverHeight, 140, 280, d.momentsCoverHeight),
            momentsNameSize: clampInt(raw.momentsNameSize ?? d.momentsNameSize, 12, 24, d.momentsNameSize),
            momentsTextSize: clampInt(raw.momentsTextSize ?? d.momentsTextSize, 12, 22, d.momentsTextSize),
            momentsMetaSize: clampInt(raw.momentsMetaSize ?? d.momentsMetaSize, 10, 18, d.momentsMetaSize),
            momentsComposeTextSize: clampInt(raw.momentsComposeTextSize ?? d.momentsComposeTextSize, 12, 24, d.momentsComposeTextSize),
            momentsComposeActionSize: clampInt(raw.momentsComposeActionSize ?? d.momentsComposeActionSize, 12, 20, d.momentsComposeActionSize),
            momentsComposeCardRadius: clampInt(raw.momentsComposeCardRadius ?? d.momentsComposeCardRadius, 0, 20, d.momentsComposeCardRadius),
            momentsComposeCellHeight: clampInt(raw.momentsComposeCellHeight ?? d.momentsComposeCellHeight, 44, 72, d.momentsComposeCellHeight),
            momentsComposeImageSize: clampInt(raw.momentsComposeImageSize ?? d.momentsComposeImageSize, 56, 120, d.momentsComposeImageSize),
            momentsComposeImageRadius: clampInt(raw.momentsComposeImageRadius ?? d.momentsComposeImageRadius, 0, 16, d.momentsComposeImageRadius),
            momentsComposeAddIconSize: clampInt(raw.momentsComposeAddIconSize ?? d.momentsComposeAddIconSize, 18, 48, d.momentsComposeAddIconSize),
            dangerBtnHeight: clampInt(raw.dangerBtnHeight ?? d.dangerBtnHeight, 32, 60, d.dangerBtnHeight),
            dangerBtnMaxWidthPct: clampInt(raw.dangerBtnMaxWidthPct ?? d.dangerBtnMaxWidthPct, 40, 100, d.dangerBtnMaxWidthPct),
            dangerBtnRadius: clampInt(raw.dangerBtnRadius ?? d.dangerBtnRadius, 0, 18, d.dangerBtnRadius),
            dangerBtnPadX: clampInt(raw.dangerBtnPadX ?? d.dangerBtnPadX, 8, 26, d.dangerBtnPadX),
            dangerBtnFontSize: clampInt(raw.dangerBtnFontSize ?? d.dangerBtnFontSize, 12, 20, d.dangerBtnFontSize),
            sceneNoteFontSize: clampInt(raw.sceneNoteFontSize ?? d.sceneNoteFontSize, 10, 20, d.sceneNoteFontSize),
            sceneNotePadX: clampInt(raw.sceneNotePadX ?? d.sceneNotePadX, 4, 24, d.sceneNotePadX),
            sceneNotePadY: clampInt(raw.sceneNotePadY ?? d.sceneNotePadY, 2, 16, d.sceneNotePadY),
