function getDraftPromptModulesFromForm() {
    const roleEl = document.getElementById('prompt-role-template');
    const protocolEl = document.getElementById('prompt-protocol-template');
    const humanEl = document.getElementById('prompt-human-template');
    return {
        role: roleEl?.value ?? '',
        protocol: protocolEl?.value ?? '',
        human: humanEl?.value ?? ''
    };
}

function getPromptPreviewContact() {
    const pageTarget = getPageTarget('prompt-page');
    if (pageTarget?.id && !isGroupSession(pageTarget)) return pageTarget;
    const currentPrivate = getCurrentPrivateContact();
    if (currentPrivate) return currentPrivate;
    if (State.currentContactId) {
        const current = State.contacts.find(c => c.id === State.currentContactId);
        if (current) return current;
    }
    if (State.contacts.length > 0) return State.contacts[0];
    return {
        id: 'preview_contact',
        name: 'AI角色',
        persona: '你是一个AI助手',
        style: '友好、自然',
        linkedWorldbooks: []
    };
}

function resolveTargetEntityById(targetId, targetType = '') {
    const id = String(targetId || '').trim();
    const type = String(targetType || '').trim();
    if (!id) return null;
    if (type === 'group') {
        const session = typeof getSessionById === 'function' ? getSessionById(id) : null;
        return isGroupSession(session) ? session : null;
    }
    if (type === 'contact') {
        return (State.contacts || []).find((item) => String(item?.id || '') === id) || null;
    }
    const session = typeof getSessionById === 'function' ? getSessionById(id) : null;
    if (isGroupSession(session)) return session;
    return (State.contacts || []).find((item) => String(item?.id || '') === id) || null;
}

function getEntityDisplayName(target) {
    if (isGroupSession(target)) return getSessionDisplayName(target);
    return getContactDisplayName(target);
}

function updateMemoryViewTitle(target) {
    const titleEl = document.getElementById('memory-view-title');
    if (!titleEl) return;
    titleEl.textContent = target?.id
        ? `以往记忆 · ${getEntityDisplayName(target)}`
        : '以往记忆';
}

function updatePromptViewTitle(target) {
    const titleEl = document.getElementById('prompt-view-title');
    if (!titleEl) return;
    titleEl.textContent = target?.id
        ? `查看提示词 · ${getEntityDisplayName(target)}`
        : '查看提示词';
}

function setPageTarget(pageId, target, targetType = '') {
    const page = document.getElementById(pageId);
    if (!page) return;
    const id = String(target?.id || '').trim();
    page.dataset.targetId = id;
    page.dataset.targetType = targetType || (isGroupSession(target) ? 'group' : 'contact');
}

function getPageTarget(pageId) {
    const page = document.getElementById(pageId);
    if (!page) return null;
    return resolveTargetEntityById(page.dataset.targetId, page.dataset.targetType);
}

function getPromptPreviewSession() {
    const pageTarget = getPageTarget('prompt-page');
    if (isGroupSession(pageTarget)) return pageTarget;
    const current = getCurrentSession();
    if (isGroupSession(current)) return current;
    const existing = (State.sessions || []).find((item) => isGroupSession(item));
    if (existing) return existing;
    const previewMemberIds = (State.contacts || []).slice(0, 3).map((item) => String(item?.id || '').trim()).filter(Boolean);
    return {
        id: 'group_preview_session',
        type: 'group',
        name: '宿舍摸鱼群',
        announcement: '今晚记得交作业',
        memberIds: previewMemberIds
    };
}

function getPromptPreviewGroupMembers() {
    const session = getPromptPreviewSession();
    const fromSession = isGroupSession(session) ? getGroupMemberContacts(session) : [];
    if (fromSession.length > 0) return fromSession;
    const picked = (State.contacts || []).slice(0, 3);
    if (picked.length > 0) return picked;
    return [
        { id: 'group_preview_member_1', name: '小助手', remarkName: '小助手', style: '活泼，会接话，也会调侃两句', avatar: 'user' },
        { id: 'group_preview_member_2', name: '阿宁', remarkName: '阿宁', style: '嘴硬一点，偶尔会吐槽', avatar: 'user' },
        { id: 'group_preview_member_3', name: '圆圆', remarkName: '圆圆', style: '爱吃瓜，会追问', avatar: 'user' }
    ];
}

function findGroupMemberFromList(memberId, members = []) {
    const id = String(memberId || '').trim();
    return (Array.isArray(members) ? members : []).find((item) => String(item?.id || '') === id) || null;
}

function buildGroupMemberPromptProfiles(members = []) {
    const list = Array.isArray(members) ? members.filter(Boolean) : [];
    return list.map((item, index) => {
        const displayName = getContactDisplayName(item);
        const rawName = String(item?.name || '').trim();
        const remarkName = String(item?.remarkName || '').trim();
        const persona = String(item?.persona || '').trim() || '未单独填写';
        const style = String(item?.style || '').trim() || '自然聊天';
        const aliases = Array.from(new Set([displayName, rawName, remarkName].filter(Boolean))).join(' / ');
        return [
            `- 成员${index + 1}：${displayName}`,
            `  可识别名字：${aliases || displayName}`,
            `  人设：${persona}`,
            `  说话风格：${style}`
        ].join('\n');
    }).join('\n');
}

function getGroupAiVisibleContextLimit(session, member = null) {
    const sessionLimit = Math.max(0, parseInt(session?.groupContextLimit ?? 0, 10) || 0);
    if (sessionLimit > 0) return sessionLimit;
    return Math.max(1, parseInt(member?.contextLimit ?? 150, 10) || 150);
}

function getGroupAiVisibleHistory(session, member = null) {
    if (!isGroupSession(session)) return [];
    const history = getSessionHistory(session.id);
    const limit = getGroupAiVisibleContextLimit(session, member);
    return history.slice(-limit);
}

function buildMemoryRecallQueryText(history = [], triggerText = '') {
    const list = Array.isArray(history) ? history : [];
    const historyLines = list
        .slice(-6)
        .map((item) => {
            if (typeof item === 'string') return String(item).trim();
            return toPlainTextFromStoredContent(item?.content);
        })
        .filter(Boolean);
    const trigger = String(triggerText || '').trim();
    return [...historyLines, trigger].filter(Boolean).join('\n').trim();
}

function getGroupChatPromptPreviewRuntime() {
    const session = getPromptPreviewSession();
    const members = getPromptPreviewGroupMembers();
    const fallbackMember = members[0] || { id: 'group_preview_member_main', name: '小助手', remarkName: '小助手', style: '自然聊天' };
    const liveHistory = isGroupSession(session) ? getGroupAiVisibleHistory(session, fallbackMember) : [];
    const sampleHistory = [
        { role: 'user', content: '今晚谁还没睡' },
        { role: 'assistant', content: '我还在写东西', senderId: fallbackMember.id },
        { role: 'assistant', content: '我刚洗完澡', senderId: String((members[1]?.id) || fallbackMember.id) }
    ];
    const history = liveHistory.length > 0 ? liveHistory : sampleHistory;
    const liveTriggerText = isGroupSession(session) ? getLatestGroupUserTriggerText(session) : '';
    const triggerText = String(liveTriggerText || `@${getContactDisplayName(fallbackMember)} 你吃饭了吗`).trim();
    let mentionedMembers = isGroupSession(session) ? getMentionedGroupMembers(session, triggerText) : [];
    if (mentionedMembers.length === 0 && fallbackMember?.id) mentionedMembers = [fallbackMember];
    const mentionedMemberIds = mentionedMembers.map((item) => String(item?.id || '')).filter(Boolean);
    const member = mentionedMembers[0] || fallbackMember;
    return {
        session,
        members,
        member,
        triggerText,
        history,
        mentionedMemberIds,
        isLive: liveHistory.length > 0
    };
}

function buildGroupReplyPromptBundle(session, member, options = {}) {
    const prefs = State.promptPrefs || Storage.DEFAULT_PROMPT_PREFS;
    const modules = getEffectivePromptModules();
    const members = Array.isArray(options.members) && options.members.length > 0
        ? options.members.filter(Boolean)
        : getGroupMemberContacts(session);
    const history = Array.isArray(options.history) ? options.history : getGroupAiVisibleHistory(session, member);
    const mentionedMemberIds = Array.isArray(options.mentionedMemberIds) ? options.mentionedMemberIds.map((id) => String(id || '')) : [];
    const respondedMemberIds = Array.isArray(options.respondedMemberIds) ? options.respondedMemberIds.map((id) => String(id || '')) : [];
    const triggerText = String(options.triggerText || '').trim();
    const summaryMemory = String(options.summaryMemoryText || getLatestSummaryText(session.id) || '').trim();
    const userProfile = getUserProfileForContact(member);
    const memberProfilesText = buildGroupMemberPromptProfiles(members);
    const stickerCandidateCount = Math.max(1, Math.min(20, parseInt(prefs.stickerCandidateCount ?? 8, 10) || 8));
    const stickerCandidates = Array.isArray(options.stickerCandidates)
        ? options.stickerCandidates.filter(Boolean)
        : buildStickerPromptCandidates(member, stickerCandidateCount);
    const imageRange = normalizeImageDescRange(prefs.imageDescMinChars ?? 25, prefs.imageDescMaxChars ?? 60);
    const imageLenMap = {
        short: '图片描述控制为 1 句话，尽量不超过 25 字。',
        medium: '图片描述控制为 1-2 句话，建议 25-60 字。',
        long: '图片描述可写 2-4 句话，建议 60-140 字。',
        custom: `图片描述尽量控制在 ${imageRange.min}-${imageRange.max} 字之间，过短可适当补足，过长请精简。`
    };
    const now = new Date();
    const knowsRealTime = !!member?.knowsRealTime;
    const vars = {
        char: String(member?.name || getContactDisplayName(member) || '群成员').trim() || '群成员',
        role: String(member?.name || getContactDisplayName(member) || '群成员').trim() || '群成员',
        persona: String(member?.persona || '').trim(),
        style: String(member?.style || '').trim(),
        user: String(userProfile.nickname || '我').trim() || '我',
        wxid: String(userProfile.wxid || '').trim(),
        date: knowsRealTime ? now.toLocaleDateString('zh-CN') : '',
        time: knowsRealTime ? `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}` : '',
        timezone: knowsRealTime ? (Intl.DateTimeFormat().resolvedOptions().timeZone || 'Local') : ''
    };
    vars.persona = renderPromptTemplate(vars.persona, vars);
    vars.style = renderPromptTemplate(vars.style, vars);
    const renderedRolePrompt = renderPromptTemplate(modules.role || '', vars).trim();
    const renderedHumanPrompt = renderPromptTemplate(modules.human || '', vars).trim();
    const renderedProtocolPrompt = renderPromptTemplate(modules.protocol || '', vars).trim();
    const renderedGlobalPrompt = renderPromptTemplate(State.globalPrompt || '', vars).trim();
    const chaotic = /跳脱|神经|抽象|发癫|疯|中二|胡言|乱语|沙雕|梗|癫/i.test(`${vars.persona}\n${vars.style}`);
    const mentionedNames = mentionedMemberIds
        .map((id) => findGroupMemberFromList(id, members) || (State.contacts || []).find((item) => String(item?.id || '') === id))
        .filter(Boolean)
        .map((item) => getContactDisplayName(item));
    const respondedNames = respondedMemberIds
        .map((id) => findGroupMemberFromList(id, members) || (State.contacts || []).find((item) => String(item?.id || '') === id))
        .filter(Boolean)
        .map((item) => getContactDisplayName(item));
    const isDirectlyMentioned = mentionedMemberIds.includes(String(member?.id || ''));
    const groupOfflineConfig = getGroupOfflineModeConfig(session);
    const onlineModeResetAddon = !groupOfflineConfig.enabled && hasOfflineSceneItems(history, triggerText)
        ? buildGroupOnlineModeResetPromptAddon(session, member, { userProfile, history, triggerText })
        : '';
    const offlinePromptAddon = groupOfflineConfig.enabled
        ? buildGroupOfflineModePromptAddon(session, member, { userProfile, history, triggerText, config: groupOfflineConfig })
        : '';
    const lines = history.map((msg) => {
        let senderName = '系统';
        if (msg?.role === 'user') {
            senderName = userProfile.nickname || '我';
        } else if (msg?.role === 'assistant') {
            const sender = findGroupMemberFromList(msg?.senderId, members)
                || (State.contacts || []).find((item) => String(item?.id || '') === String(msg?.senderId || ''))
                || member;
            senderName = getContactDisplayName(sender);
        }
        return `${senderName}：${toPlainTextFromStoredContent(msg?.content, {
            messageRole: msg?.role,
            userLabel: userProfile.nickname || '我',
            assistantLabel: senderName,
            sceneNoteMode: onlineModeResetAddon ? 'history_reference' : 'offline'
        })}`;
    }).join('\n');
    const memberList = members.map((item) => getContactDisplayName(item)).join('、');
    const systemLines = [];
    const unrestrictedPrefix = buildUnrestrictedPromptPrefix();
    if (unrestrictedPrefix) systemLines.push(unrestrictedPrefix);
    if (renderedRolePrompt) systemLines.push(renderedRolePrompt);
    if (renderedHumanPrompt) systemLines.push(renderedHumanPrompt);
    systemLines.push([
        '【群聊名字映射】',
        `- 你自己是：${getContactDisplayName(member)}`,
        `- 用户本人是：${userProfile.nickname || '我'}`,
        `- 当前群名：${getSessionDisplayName(session)}`,
        `- 群成员：${userProfile.nickname || '我'}、${memberList || '暂无其他成员'}`
    ].join('\n'));
    if (renderedGlobalPrompt) {
        systemLines.push(`【全局设定】\n${renderedGlobalPrompt}`);
    }
    if (summaryMemory) {
        systemLines.push(`【已归档群聊记忆】\n以下是这个群之前整理出的记忆，请把它当成群聊长期上下文，不要把所有人混成一个人。\n${summaryMemory}`);
    }
    if (userProfile.userPersona) {
        systemLines.push(`【关于用户】\n用户的身份与设定：${userProfile.userPersona}`);
    }
    if (knowsRealTime) {
        systemLines.push(`【当前时间状态】\n现在是真实时间的 ${now.toLocaleString('zh-CN', { hour12: false })} (${vars.timezone || 'Local'})。\n请让你的回复符合当前时间语境，不要在半夜说早安。`);
    }
    systemLines.push(`【用户偏好约束】\n1. ${imageLenMap[prefs.imageDescLength] || imageLenMap.medium}\n2. ${prefs.extraRules || '无额外要求时，保持自然聊天语气并避免过度堆砌修辞。'}`);
    if (renderedProtocolPrompt) {
        systemLines.push(renderedProtocolPrompt);
    }
    if (offlinePromptAddon) {
        systemLines.push(offlinePromptAddon);
    }
    if (onlineModeResetAddon) {
        systemLines.push(onlineModeResetAddon);
    }
    systemLines.push([
        '【群聊模式补充输出规则】',
        '- 群聊里也沿用微信聊天协议：表情包、图片卡片、引用回复、红包/转账卡片都按上面的 JSON 规则输出。',
        '- 群聊里默认优先输出可见消息气泡；不要乱用会改群内昵称、换头像、拍一拍、撤回之类的 action。',
        '- 但 `WX_MONEY_ACCEPT` 不算乱用 action：如果群里刚有人给你发了红包或转账，而且按你的人设会顺手领，就可以直接输出这个 action。',
        '- `WX_PAT` 和 `WX_RECALL_LAST / WX_RECALL_OFFSET` 也允许用，但要克制，只有你真会这么做时才用。',
        '- 如果要撤回，只能撤回你自己刚刚发过的消息，不能撤回别的群成员的消息。',
        '- `WX_CALL_START` 允许你发起语音/视频通话，来电人就是你自己。',
        '- `WX_AVATAR_SET` 只会修改你自己的头像，不会改别的群成员头像；`source:"last_user_image"` 会拿用户最近在本群发的图片。',
        '- `WX_REMARK_SET` 在群聊里表示修改群内昵称：target:"user" 是 {char} 给 {user} 设置的群内昵称；target:"contact"/"self"/"member" 是 {user} 给当前这个群成员设置的群内昵称。',
        '- 红包和转账如果要发，请直接用 text/text_message 的三行卡片格式输出。',
        '- 回复尽量 1 到 2 句，简短自然，不要写说明，不要加 markdown。'
    ].join('\n'));
    if (!session?.allowOfflineSameLocation) {
        systemLines.push('【群聊空间关系】\n- 群聊里的语音/视频通话默认是远程通话：每个人都在各自不同的地点，通过自己的手机镜头或麦克风出现在画面/声音里，不是在同一个房间面对面，也不要写成伸手碰到彼此、并排坐着、共用同一空间镜头那种场景。');
    }
    if (member?.allowSeenNoReply) {
        const cooldownMin = Math.max(1, Math.min(120, parseInt(member?.noReplyCooldownMin ?? 10, 10) || 10));
        const tendency = Math.max(0, Math.min(100, parseInt(member?.noReplyTendency ?? 30, 10) || 30));
        systemLines.push(`【NO_REPLY】\n- 你当前允许已读不回，但必须非常克制；如果要用，只输出 [{"type":"action","command":"NO_REPLY"}] 这一项。\n- 冷处理倾向：${tendency}/100。\n- 冷却时间：${cooldownMin} 分钟。\n- 如果这轮已经被明确@到，除非你的人设就是故意晾着，否则尽量不要用。`);
    } else {
        systemLines.push('【NO_REPLY】\n- 这轮群聊禁止已读不回，不要输出 NO_REPLY。');
    }
    if (stickerCandidates.length > 0) {
        const candidateText = stickerCandidates.map((item) => item.name).filter(Boolean).join('；');
        systemLines.push(`【当前可用表情包候选】\n你可以使用 sticker_message 发送表情。\n直接在 sticker 字段填写候选备注名，不要写解释文字。\n推荐格式：{"type":"sticker_message","sticker":"开心"}\n只在这些候选里选，若都不合适就正常发文字，不要硬发表情。\n候选清单：${candidateText}`);
    }
    if (chaotic) {
        systemLines.push('（补充）你允许偶尔跳脱一句梗，但要短，而且下一条要立刻拉回当前对话。');
    }
    systemLines.push([
        `你现在在扮演微信群成员「${getContactDisplayName(member)}」。`,
        `你自己的人设：${String(vars.persona || '未单独填写').trim() || '未单独填写'}。`,
        `你自己的说话风格：${String(vars.style || member?.persona || '自然聊天').trim() || '自然聊天'}。`,
        '下面是这个群里每个群成员的资料，回复时要分清谁是谁，不要把所有人混成一个模糊的“别人”。',
        '【群成员资料】',
        memberProfilesText || '- 暂无其他成员资料'
    ].join('\n'));
    systemLines.push(triggerText ? `用户刚发的内容：${triggerText}` : '请结合最近群聊，继续自然接话。');
    systemLines.push(mentionedNames.length ? `这次消息里被@的人：${mentionedNames.join('、')}。` : '这次没有明确点名某个成员。');
    systemLines.push(
        isDirectlyMentioned
            ? '你就是被@的人之一，优先正面接住用户的话，先回答再自然延伸。'
            : (mentionedNames.length
                ? '这次主要被点名的不是你。你可以顺着话题补一句、吐槽、疑问、调侃、吃醋、附和，但不要抢成主角。'
                : '没有人被单独点名，你就按自己的性格自然参与群聊。')
    );
    systemLines.push(respondedNames.length ? `已经先开口的人：${respondedNames.join('、')}。你可以接着他们刚才的话往下聊。` : '你是这一轮里较早开口的人，可以先起话头。');
    systemLines.push(`这是本轮群聊互动里的第 ${Math.max(1, Number(options.participantIndex || 0) + 1)} 个发言成员，共 ${Math.max(1, Number(options.participantTotal || 1))} 个成员会参与。`);
    systemLines.push('如果你不是主要被@的人，就不要装作自己被点名；但你可以像真实群友一样接梗、插话、起哄、关心或追问。');
    const systemPrompt = systemLines.filter(Boolean).join('\n\n');
    const forceReplyHint = options.forceReply
        ? '\n\n（系统要求）本轮禁止已读不回。你必须输出至少一条可见消息，不能只输出 action。'
        : '';
    const userPrompt = `这是最近群聊记录：\n${lines || '（暂无历史消息）'}\n\n请你以「${getContactDisplayName(member)}」身份，在这个群里顺着刚才的话自然接一句。${forceReplyHint}`;
    return {
        systemPrompt,
        userPrompt,
        stickerCandidates,
        traceText: buildPromptTraceFromMessages([
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt }
        ])
    };
}

function estimateTokenCount(text) {
    if (!text) return 0;
    return Math.max(1, Math.ceil(text.length * 0.7));
}

function buildPromptPreviewText(previewContact, mode) {
    const previewMode = String(mode || 'chat');
    if (previewMode === 'chat') {
        const basePrompt = buildSystemPrompt(previewContact);
        const offlineConfig = getOfflineModeConfig(previewContact);
        const offlineAddon = offlineConfig.enabled ? buildOfflineModePromptAddon(previewContact, offlineConfig) : '';
        return offlineAddon ? `${basePrompt}\n\n${offlineAddon}` : basePrompt;
    }
    if (previewMode === 'group-chat') {
        const runtime = getGroupChatPromptPreviewRuntime();
        const bundle = buildGroupReplyPromptBundle(runtime.session, runtime.member, {
            members: runtime.members,
            triggerText: runtime.triggerText,
            history: runtime.history,
            mentionedMemberIds: runtime.mentionedMemberIds,
            participantIndex: 0,
            participantTotal: Math.max(1, runtime.members.length)
        });
        return bundle.traceText;
    }
    if (previewMode === 'proactive') {
        return [
            '【聊天 System Prompt】',
            buildSystemPrompt(previewContact),
            '',
            '【主动发消息附加提示】',
            buildProactivePrompt(previewContact)
        ].join('\n');
    }
    if (previewMode === 'moments-post') {
        const pair = buildMomentPostPromptPair(previewContact, {
            recentChat: '我：你中午吃了吗\n对方：刚下课准备去吃',
            memoryText: '最近你们聊天比较自然，对方这周都在上课，晚上会刷视频放松。'
        });
        return `【System】\n${pair.systemPrompt}\n\n【User】\n${pair.userPrompt}`;
    }
    if (previewMode === 'moments-interaction') {
        const pair = buildMomentInteractionPromptPair(previewContact, {
            text: '今天的课终于结束了，食堂阿姨手居然没抖'
        });
        return `【System】\n${pair.systemPrompt}\n\n【User】\n${pair.userPrompt}`;
    }
    if (previewMode === 'moments-reply') {
        const pair = buildMomentReplyPromptPair(previewContact, { text: '今天风好大，差点把伞吹飞' }, [
            { id: 'c1', text: '哈哈哈哈你那把伞是不是又不行了', byType: 'user', byId: 'me' },
            { id: 'c2', text: '注意别感冒', byType: 'contact', byId: 'friend_a' }
        ]);
        return `【System】\n${pair.systemPrompt}\n\n【User】\n${pair.userPrompt}`;
    }
    if (previewMode === 'moments-social') {
        const pair = buildMomentSocialPromptPair(previewContact, { text: '今天终于把课题改完了，脑子快转不动了' }, {
            recentChat: '我：你最近是不是一直在改论文\n对方：嗯，导师一直让我改',
            memoryText: '对方最近在学校忙课题，身边经常提到导师、室友和家里人。'
        });
        return `【System】\n${pair.systemPrompt}\n\n【User】\n${pair.userPrompt}`;
    }
    if (previewMode === 'call') {
        const systemPrompt = buildCallSystemPrompt(previewContact, 'voice', '对方最近在备考，白天上课，晚上容易累。');
        const autoPrompt = buildCallAutoReplyPrompt('我刚到宿舍，外面风特别大\n你今天怎么样', true);
        return `【System】\n${systemPrompt}\n\n【快捷接话附加提示】\n${autoPrompt}`;
    }
    if (previewMode === 'summary-mini') {
        const basePrompt = getSummaryBasePrompt(previewContact, 'mini');
        return buildMiniSummaryPromptText(basePrompt, '', '[user]: 我今晚还得写报告\n[assistant]: 那你先忙完再说');
    }
    if (previewMode === 'summary-mega') {
        const basePrompt = getSummaryBasePrompt(previewContact, 'mega');
        return buildMegaSummaryPromptText(basePrompt, '【我和 {user} 最近】\n- 最近刚和好，聊天比前阵子自然很多。', '【第 1 条小总结】\n- {user} 最近在赶作业，晚上常常很累。\n\n【第 2 条小总结】\n- {user} 不太喜欢我在她忙的时候连续追问。', { summaryCount: 2 });
    }
    if (previewMode === 'group-summary-mini') {
        const session = getPromptPreviewSession();
        const sampleChat = [
            '[2026/05/16 21:03][我]: @小助手 你吃饭了吗',
            '[2026/05/16 21:04][小助手]: 刚吃完，你呢',
            '[2026/05/16 21:04][阿宁]: 你怎么只问她',
            '[2026/05/16 21:05][圆圆]: 我闻到一股醋味'
        ].join('\n');
        return buildMiniSummaryPromptText(getSummaryBasePrompt(session, 'mini'), '', sampleChat);
    }
    if (previewMode === 'group-summary-mega') {
        const session = getPromptPreviewSession();
        const sampleSummaries = [
            '【第 1 条小总结】\n- 这周群里一直在聊作业和晚饭，@到的人会先接话，其他人会跟着起哄。',
            '【第 2 条小总结】\n- 小助手最近说话偏温柔，阿宁容易嘴硬吃醋，圆圆喜欢围观追问。'
        ].join('\n\n');
        return buildMegaSummaryPromptText(getSummaryBasePrompt(session, 'mega'), '【之前的大总结】\n- 这个群平时气氛偏熟人打闹，话题经常从正经事歪到互相调侃。', sampleSummaries, { summaryCount: 2 });
    }
    return buildSystemPrompt(previewContact);
}

function updatePromptPreviewContextHint(mode) {
    const hintEl = document.getElementById('prompt-preview-context-hint');
    if (!hintEl) return;
    const previewMode = String(mode || 'chat').trim();
    if (previewMode === 'group-chat') {
        const runtime = getGroupChatPromptPreviewRuntime();
        const historyCount = Array.isArray(runtime.history) ? runtime.history.length : 0;
        const triggerText = String(runtime.triggerText || '').trim();
        hintEl.textContent = runtime.isLive
            ? `当前显示的是群聊「${getSessionDisplayName(runtime.session)}」本轮会发给 AI 的提示词预览，会读取最近 ${historyCount} 条群消息，并按最近一次用户发言生成。`
            : `当前没有可用的真实群聊上下文，下面先显示一份群聊互动示例提示词。触发词示例：${triggerText || '无'}`;
        return;
    }
    if (previewMode === 'group-summary-mini' || previewMode === 'group-summary-mega') {
        const session = getPromptPreviewSession();
        hintEl.textContent = `当前显示的是群聊「${getSessionDisplayName(session)}」的总结提示词预览。`;
        return;
    }
    hintEl.textContent = '这里显示当前模式最终会注入给模型的提示词预览。';
}

function setPromptAddonPreview(wrapId, previewId, hintId, content, hintText) {
    const wrapEl = document.getElementById(wrapId);
    const previewEl = document.getElementById(previewId);
    const hintEl = document.getElementById(hintId);
    const text = String(content || '').trim();
    if (wrapEl) wrapEl.style.display = text ? 'block' : 'none';
    if (previewEl) previewEl.value = text;
    if (hintEl && text) hintEl.textContent = hintText;
}

function refreshGroupPromptModule() {
    const previewEl = document.getElementById('prompt-group-chat-preview');
    const hintEl = document.getElementById('prompt-group-chat-context-hint');
    const tokenEl = document.getElementById('group-prompt-token-count');
    if (!previewEl) return;
    try {
        const runtime = getGroupChatPromptPreviewRuntime();
        const bundle = buildGroupReplyPromptBundle(runtime.session, runtime.member, {
            members: runtime.members,
            triggerText: runtime.triggerText,
            history: runtime.history,
            mentionedMemberIds: runtime.mentionedMemberIds,
            participantIndex: 0,
            participantTotal: Math.max(1, runtime.members.length)
        });
        previewEl.value = bundle.traceText;
        if (tokenEl) tokenEl.textContent = String(estimateTokenCount(bundle.traceText));
        setPromptAddonPreview(
            'prompt-group-offline-addon-wrap',
            'prompt-group-offline-addon-preview',
            'prompt-group-offline-addon-hint',
            '',
            ''
        );
        if (hintEl) {
            const historyCount = Array.isArray(runtime.history) ? runtime.history.length : 0;
            hintEl.textContent = runtime.isLive
                ? `当前显示的是群聊「${getSessionDisplayName(runtime.session)}」实际会发给 AI 的提示词，已读取最近 ${historyCount} 条群消息，并按最近一次用户发言来生成。`
                : `当前没有可用的真实群聊上下文，这里先显示一份群聊互动示例提示词。`;
        }
    } catch (err) {
        console.error('群聊提示词模块生成失败:', err);
        previewEl.value = '群聊提示词生成失败，请检查当前群聊数据。';
        if (tokenEl) tokenEl.textContent = '0';
        if (hintEl) hintEl.textContent = '当前群聊提示词生成失败。';
        setPromptAddonPreview('prompt-group-offline-addon-wrap', 'prompt-group-offline-addon-preview', 'prompt-group-offline-addon-hint', '', '');
    }
}

function refreshPromptPreview() {
    const previewEl = document.getElementById('prompt-final-preview');
    if (!previewEl) return;

    const globalPromptInput = document.getElementById('global-prompt');
    const nextGlobalPrompt = globalPromptInput?.value || '';
    const nextPrefs = getDraftPromptPrefsFromForm();
    const nextModules = getDraftPromptModulesFromForm();
    const nextScenarioTemplates = getDraftPromptScenarioTemplatesFromForm();
    const nextScenarioContext = getDraftPromptScenarioContextFromForm();
    const previewMode = document.getElementById('prompt-preview-mode')?.value || 'chat';
    const summaryMiniDraft = document.getElementById('prompt-summary-mini-template')?.value || '';
    const summaryMegaDraft = document.getElementById('prompt-summary-mega-template')?.value || '';
    const previewContact = getPromptPreviewContact();
    const prevGlobalPrompt = State.globalPrompt;
    const prevPrefs = State.promptPrefs;
    const prevModules = State.promptModules;
    const prevScenarioTemplates = State.promptScenarioTemplates;
    const prevScenarioContext = State.promptScenarioContext;
    const prevSummaryConfig = State.summaryConfig;

    try {
        // 临时替换为表单草稿，实时预览最终注入效果
        State.globalPrompt = replaceLegacyPromptVars(nextGlobalPrompt);
        State.promptPrefs = nextPrefs;
        State.promptModules = { ...Storage.DEFAULT_PROMPT_MODULES, ...normalizePromptModules(nextModules || {}) };
        State.promptScenarioTemplates = { ...Storage.DEFAULT_PROMPT_SCENARIO_TEMPLATES, ...normalizePromptTemplateMap(nextScenarioTemplates || {}) };
        State.promptScenarioContext = { ...Storage.DEFAULT_PROMPT_SCENARIO_CONTEXT, ...(nextScenarioContext || {}) };
        State.summaryConfig = {
            ...(State.summaryConfig || {}),
            customPromptMini: replaceLegacyPromptVars(summaryMiniDraft),
            customPromptMega: replaceLegacyPromptVars(summaryMegaDraft),
            customPrompt: replaceLegacyPromptVars(summaryMiniDraft)
        };
        refreshGroupPromptModule();
        const previewText = buildPromptPreviewText(previewContact, previewMode);
        updatePromptPreviewContextHint(previewMode);
        previewEl.value = previewText;
        setPromptAddonPreview(
            'prompt-offline-addon-wrap',
            'prompt-offline-addon-preview',
            'prompt-offline-addon-hint',
            '',
            ''
        );
        const tokenEl = document.getElementById('token-count');
        if (tokenEl) tokenEl.textContent = String(estimateTokenCount(previewText));
    } catch (err) {
        console.error('提示词预览生成失败:', err);
        refreshGroupPromptModule();
        updatePromptPreviewContextHint(previewMode);
        previewEl.value = '预览生成失败，请检查配置。';
        setPromptAddonPreview('prompt-offline-addon-wrap', 'prompt-offline-addon-preview', 'prompt-offline-addon-hint', '', '');
    } finally {
        State.globalPrompt = prevGlobalPrompt;
        State.promptPrefs = prevPrefs;
        State.promptModules = prevModules;
        State.promptScenarioTemplates = prevScenarioTemplates;
        State.promptScenarioContext = prevScenarioContext;
        State.summaryConfig = prevSummaryConfig;
    }
}

function bindPromptPreviewEvents() {
    const promptPage = document.getElementById('prompt-page');
    if (!promptPage || promptPage.dataset.previewBound === '1') return;
    promptPage.dataset.previewBound = '1';

    [
        'global-prompt',
        'prompt-image-length',
        'prompt-image-min-chars',
        'prompt-image-max-chars',
        'prompt-extra-rules',
        'prompt-sticker-candidate-count',
        'prompt-role-template',
        'prompt-protocol-template',
        'prompt-human-template',
        'prompt-proactive-template',
        'prompt-offline-chat-template',
        'prompt-moments-post-system-template',
        'prompt-moments-post-user-template',
        'prompt-moments-interaction-system-template',
        'prompt-moments-interaction-user-template',
        'prompt-moments-reply-system-template',
        'prompt-moments-reply-user-template',
        'prompt-moments-social-system-template',
        'prompt-moments-social-user-template',
        'prompt-group-offline-template',
        'prompt-call-system-template',
        'prompt-call-auto-reply-template',
        'prompt-summary-mini-template',
        'prompt-summary-mega-template',
        'prompt-moments-recent-chat-lines',
        'prompt-moments-memory-max-chars',
        'prompt-moments-reply-batch-size',
        'prompt-moments-social-max-actors',
        'prompt-moments-social-max-comments',
        'prompt-call-recent-chat-lines',
        'prompt-call-live-history-lines',
        'prompt-call-auto-user-count',
        'prompt-preview-mode'
    ].forEach((id) => {
        const el = document.getElementById(id);
        if (!el) return;
        el.addEventListener('input', refreshPromptPreview);
        el.addEventListener('change', refreshPromptPreview);
    });
}

function bindUnrestrictedEvents() {
    if (bindUnrestrictedEvents._bound) return;
    bindUnrestrictedEvents._bound = true;

    const saveConfig = (nextConfig, toastText = '') => {
        State.unrestrictedConfig = normalizeUnrestrictedConfig(nextConfig);
        Storage.saveUnrestrictedConfig(State.unrestrictedConfig);
        refreshUnrestrictedUi();
        if (toastText) showToast(toastText);
    };

    document.getElementById('chat-unrestricted-btn')?.addEventListener('click', () => {
        openUnrestrictedModal();
    });
    document.getElementById('chat-offline-mode-btn')?.addEventListener('click', () => {
        openOfflineModeModal();
    });
    document.getElementById('close-offline-mode-modal')?.addEventListener('click', () => {
        closeOfflineModeModal();
    });
    document.querySelector('#offline-mode-modal .modal-overlay')?.addEventListener('click', () => {
        closeOfflineModeModal();
    });
    document.getElementById('offline-mode-toggle')?.addEventListener('click', function () {
        this.classList.toggle('active');
    });
    document.getElementById('offline-mode-save-btn')?.addEventListener('click', () => {
        saveOfflineModeConfigForCurrentTarget();
    });
    document.getElementById('unrestricted-overlay')?.addEventListener('click', () => {
        closeUnrestrictedModal();
    });
    document.getElementById('unrestricted-close-btn')?.addEventListener('click', () => {
        closeUnrestrictedModal();
    });
    document.getElementById('unrestricted-master-toggle')?.addEventListener('click', function () {
        const next = normalizeUnrestrictedConfig(State.unrestrictedConfig);
        next.enabled = !next.enabled;
        saveConfig(next, next.enabled ? '无限制已开启' : '无限制已关闭');
        const summary = getUnrestrictedSelectionSummary(next);
        if (next.enabled && summary.enabledCount === 0) {
            showToast('已开启，但还没有勾选可用方案');
        }
    });
    document.getElementById('unrestricted-select-all-btn')?.addEventListener('click', () => {
        const next = normalizeUnrestrictedConfig(State.unrestrictedConfig);
        next.activeSchemeIds = next.schemes.map((scheme) => scheme.id);
        saveConfig(next, '已全选方案');
    });
    document.getElementById('unrestricted-clear-all-btn')?.addEventListener('click', () => {
        const next = normalizeUnrestrictedConfig(State.unrestrictedConfig);
        next.activeSchemeIds = [];
        saveConfig(next, '已清空勾选');
    });
    document.getElementById('unrestricted-add-btn')?.addEventListener('click', () => {
        openUnrestrictedEditModal();
    });

    document.getElementById('unrestricted-scheme-list')?.addEventListener('change', (e) => {
        const checkbox = e.target.closest('.unrestricted-scheme-checkbox');
        const item = e.target.closest('.unrestricted-scheme-item');
        if (!checkbox || !item) return;
        const id = item.dataset.id ? decodeURIComponent(item.dataset.id) : '';
        if (!id) return;
        const next = normalizeUnrestrictedConfig(State.unrestrictedConfig);
        const selected = new Set(next.activeSchemeIds || []);
        if (checkbox.checked) selected.add(id);
        else selected.delete(id);
        next.activeSchemeIds = next.schemes.map((scheme) => scheme.id).filter((schemeId) => selected.has(schemeId));
        saveConfig(next, checkbox.checked ? '已启用方案' : '已停用方案');
    });

    document.getElementById('unrestricted-scheme-list')?.addEventListener('click', async (e) => {
        const actionBtn = e.target.closest('[data-action]');
        const item = e.target.closest('.unrestricted-scheme-item');
        if (!item || !actionBtn) return;
        const id = item.dataset.id ? decodeURIComponent(item.dataset.id) : '';
        if (!id) return;
        const action = String(actionBtn.dataset.action || '').trim();
        if (action === 'edit') {
            openUnrestrictedEditModal(id);
            return;
        }
        if (action === 'delete') {
            const next = normalizeUnrestrictedConfig(State.unrestrictedConfig);
            const scheme = next.schemes.find((entry) => entry.id === id);
            if (!scheme) return;
            const ok = await WeChatUI.showConfirm('删除方案', `确定删除「${scheme.name || '未命名方案'}」吗？`, '删除', '取消', true);
            if (!ok) return;
            next.schemes = next.schemes.filter((entry) => entry.id !== id);
            next.activeSchemeIds = next.activeSchemeIds.filter((schemeId) => schemeId !== id);
            saveConfig(next, '方案已删除');
        }
    });

    document.getElementById('unrestricted-edit-overlay')?.addEventListener('click', () => {
        closeUnrestrictedEditModal();
    });
    document.getElementById('unrestricted-edit-cancel')?.addEventListener('click', () => {
        closeUnrestrictedEditModal();
    });
    document.getElementById('unrestricted-edit-save')?.addEventListener('click', () => {
        const modal = document.getElementById('unrestricted-edit-modal');
        const nameEl = document.getElementById('unrestricted-edit-name');
        const contentEl = document.getElementById('unrestricted-edit-content');
        const editingId = String(modal?.dataset?.editingId || '').trim();
        const content = String(contentEl?.value || '').replace(/\r\n?/g, '\n').trim();
        const next = normalizeUnrestrictedConfig(State.unrestrictedConfig);
        if (!content) {
            showToast('先写点无限制词内容吧');
            contentEl?.focus();
            return;
        }
        const fallbackName = editingId
            ? (next.schemes.find((item) => item.id === editingId)?.name || '未命名方案')
            : `方案${next.schemes.length + 1}`;
        const name = String(nameEl?.value || '').trim() || fallbackName;
        if (editingId) {
            next.schemes = next.schemes.map((item) => item.id === editingId ? { ...item, name, content } : item);
        } else {
            const id = createUnrestrictedSchemeId();
            next.schemes.push({ id, name, content });
            if (!next.activeSchemeIds.includes(id)) next.activeSchemeIds.push(id);
        }
        saveConfig(next, '方案已保存');
        closeUnrestrictedEditModal();
    });
    document.getElementById('unrestricted-edit-delete-btn')?.addEventListener('click', async () => {
        const modal = document.getElementById('unrestricted-edit-modal');
        const editingId = String(modal?.dataset?.editingId || '').trim();
        if (!editingId) return;
        const next = normalizeUnrestrictedConfig(State.unrestrictedConfig);
        const scheme = next.schemes.find((item) => item.id === editingId);
        if (!scheme) return;
        const ok = await WeChatUI.showConfirm('删除方案', `确定删除「${scheme.name || '未命名方案'}」吗？`, '删除', '取消', true);
        if (!ok) return;
        next.schemes = next.schemes.filter((item) => item.id !== editingId);
        next.activeSchemeIds = next.activeSchemeIds.filter((id) => id !== editingId);
        saveConfig(next, '方案已删除');
        closeUnrestrictedEditModal();
    });
}

// ==========================================
// 微信 Tab: 聊天记录列表
// ==========================================

function initChatList() {
    const list = document.getElementById('chat-list');
    if (!list) return;

    list.innerHTML = '';

    syncPrivateSessionsFromContacts();
    const sessions = [...(State.sessions || [])].map((session) => {
        if (!session.lastActiveAt) {
            const history = getSessionHistory(session.id);
            const last = history[history.length - 1];
            if (last?.time) session.lastActiveAt = last.time;
        }
        return session;
    }).sort((a, b) => {
        const ap = a.isPinned ? 1 : 0;
        const bp = b.isPinned ? 1 : 0;
        if (bp !== ap) return bp - ap;
        return (b.lastActiveAt || 0) - (a.lastActiveAt || 0);
    });

    sessions.forEach((session) => {
        if (!State.chatHistories[session.id]) {
            State.chatHistories[session.id] = [];
        }
        const item = document.createElement('div');
        item.className = `chat-item${session.isPinned ? ' pinned' : ''}`;
        const unreadText = getUnreadBadgeText(session.unreadCount);
        const unreadHtml = unreadText ? `<span class="chat-unread-badge">${unreadText}</span>` : '';
        item.innerHTML = `
            <div class="chat-avatar">${getAvatarHtml(getSessionAvatar(session))}${unreadHtml}</div>
            <div class="chat-info">
                <div class="chat-header-row">
                    <span class="chat-name">${escapeHtml(getSessionDisplayName(session))}</span>
                    <span class="chat-time">
                        ${session.muteNotifications ? '<i class="fas fa-bell-slash chat-flag" aria-hidden="true"></i>' : ''}
                        ${session.lastTime || ''}
                    </span>
                </div>
                <div class="chat-preview">${escapeHtml(session.lastMessage || '暂无消息')}</div>
            </div>
        `;
        item.addEventListener('click', function(e) {
            e.stopPropagation();
            openSession(session);
        });
        list.appendChild(item);
    });

    Storage.saveSessions(State.sessions);
    refreshWechatTabBadge();
}

// ==========================================
// 通讯录 Tab: AI角色管理
// ==========================================

function initContactsList() {
    const list = document.getElementById('ai-roles-list');
    if (!list) return;

    list.innerHTML = '';

    State.contacts.forEach(contact => {
        const previewText = getContactListPreviewText(contact);
        const item = document.createElement('div');
        item.className = 'contact-item';
        item.innerHTML = `
            <div class="chat-avatar">${getAvatarHtml(contact.avatar)}</div>
            <div class="chat-info">
                <div class="chat-name">${escapeHtml(getContactDisplayName(contact))}</div>
                <div class="chat-preview">${escapeHtml(previewText)}</div>
            </div>
        `;
        item.addEventListener('click', () => openRoleModal(contact));
        list.appendChild(item);
    });

    // 更新数量
    const countEl = document.getElementById('contacts-count');
    if (countEl) {
        countEl.textContent = `${State.contacts.length}个朋友`;
    }
    renderGroupSessionsList();
}

function getContactTagsText(contact) {
    const tags = normalizeContactTags(contact?.tags);
    return tags.length ? tags.map((tag) => `#${tag}`).join(' ') : '';
}

function getContactListPreviewText(contact) {
    const tagText = getContactTagsText(contact);
    const styleText = String(contact?.style || '').trim();
    if (tagText && styleText) return `${tagText} · ${styleText}`;
    return tagText || styleText || '';
}

function getContactTagStats() {
    const counts = new Map();
    (State.contacts || []).forEach((contact) => {
        normalizeContactTags(contact?.tags).forEach((tag) => {
            counts.set(tag, (counts.get(tag) || 0) + 1);
        });
    });
    return Array.from(counts.entries()).sort((a, b) => {
        if (b[1] !== a[1]) return b[1] - a[1];
        return String(a[0] || '').localeCompare(String(b[0] || ''), 'zh-CN');
    });
}

function getContactsByTag(tag) {
    const filter = String(tag || '').trim();
    const contacts = Array.isArray(State.contacts) ? State.contacts : [];
    if (!filter || filter === CONTACT_TAG_FILTER_ALL) return contacts;
    return contacts.filter((contact) => normalizeContactTags(contact?.tags).includes(filter));
}

function renderContactTagPage() {
    const filterListEl = document.getElementById('contact-tag-filter-list');
    const roleListEl = document.getElementById('contact-tag-role-list');
    const emptyEl = document.getElementById('contact-tag-empty-tip');
    if (!filterListEl || !roleListEl || !emptyEl) return;

    const tagStats = getContactTagStats();
    const filters = [
        { tag: CONTACT_TAG_FILTER_ALL, label: '全部', count: (State.contacts || []).length },
        ...tagStats.map(([tag, count]) => ({ tag, label: tag, count }))
    ];
    const activeTag = filters.some((item) => item.tag === State.contactsTagFilter)
        ? State.contactsTagFilter
        : CONTACT_TAG_FILTER_ALL;
    State.contactsTagFilter = activeTag;

    filterListEl.innerHTML = '';
    filters.forEach((item) => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = `keyword-tag contact-tag-filter${item.tag === activeTag ? ' active' : ''}`;
        chip.textContent = `${item.label}${item.tag === CONTACT_TAG_FILTER_ALL ? '' : ` (${item.count})`}`;
        chip.addEventListener('click', () => {
            State.contactsTagFilter = item.tag;
            renderContactTagPage();
        });
        filterListEl.appendChild(chip);
    });

    const filteredContacts = getContactsByTag(activeTag);
    roleListEl.innerHTML = '';
    if (filteredContacts.length === 0) {
        emptyEl.style.display = '';
        if ((State.contacts || []).length === 0) {
            emptyEl.textContent = '还没有 AI 角色';
        } else if (activeTag === CONTACT_TAG_FILTER_ALL) {
            emptyEl.textContent = '还没有可显示的角色';
        } else {
            emptyEl.textContent = `标签“${activeTag}”下还没有角色`;
        }
        return;
    }

    emptyEl.style.display = 'none';
    filteredContacts.forEach((contact) => {
        const item = document.createElement('div');
        const tagsText = getContactTagsText(contact) || '未设置标签';
        const previewText = String(contact?.style || '').trim() || '未填写聊天风格';
        item.className = 'contact-item';
        item.innerHTML = `
            <div class="chat-avatar">${getAvatarHtml(contact.avatar)}</div>
            <div class="chat-info">
                <div class="chat-name">${escapeHtml(getContactDisplayName(contact))}</div>
                <div class="chat-preview">${escapeHtml(previewText)}</div>
                <div class="contact-tag-item-meta">${escapeHtml(tagsText)}</div>
            </div>
        `;
        item.addEventListener('click', () => {
            hidePage('contact-tags-page');
            openRoleModal(contact);
        });
        roleListEl.appendChild(item);
    });
}

function openContactTagsPage(initialTag = CONTACT_TAG_FILTER_ALL) {
    State.contactsTagFilter = String(initialTag || CONTACT_TAG_FILTER_ALL).trim() || CONTACT_TAG_FILTER_ALL;
    renderContactTagPage();
    showPage('contact-tags-page');
}

function renderGroupSessionsList() {
    const list = document.getElementById('group-list-container');
    const emptyEl = document.getElementById('group-list-empty-tip');
    if (!list) return;
    const groups = (State.sessions || [])
        .filter((session) => isGroupSession(session))
        .sort((a, b) => {
            const ap = a.isPinned ? 1 : 0;
            const bp = b.isPinned ? 1 : 0;
            if (bp !== ap) return bp - ap;
            return (b.lastActiveAt || 0) - (a.lastActiveAt || 0);
        });
    list.innerHTML = '';
    if (emptyEl) emptyEl.style.display = groups.length > 0 ? 'none' : '';
    groups.forEach((session) => {
        const item = document.createElement('div');
        item.className = 'contact-item';
        const unreadText = getUnreadBadgeText(session.unreadCount);
        const unreadHtml = unreadText ? `<span class="chat-unread-badge">${unreadText}</span>` : '';
        item.innerHTML = `
            <div class="chat-avatar">${getAvatarHtml(getSessionAvatar(session))}${unreadHtml}</div>
            <div class="chat-info">
                <div class="chat-name">${escapeHtml(getSessionDisplayName(session))}</div>
                <div class="chat-preview">${escapeHtml(`${getGroupMemberContacts(session).length} 位成员`)}</div>
            </div>
        `;
        item.addEventListener('click', () => {
            hidePage('group-list-page');
            openSession(session);
        });
        list.appendChild(item);
    });
    refreshWechatTabBadge();
}

let groupCreateDraftSelectedIds = new Set();

function getGroupCreateSelectedIds() {
    return Array.from(groupCreateDraftSelectedIds.values()).filter(Boolean);
}

function updateGroupCreateSelectionUi() {
    const picked = getGroupCreateSelectedIds();
    const summaryEl = document.getElementById('group-create-selected-summary');
    const countEl = document.getElementById('group-create-selected-count');
    const stripEl = document.getElementById('group-create-selected-strip');
    if (countEl) countEl.textContent = String(picked.length);
    if (summaryEl) {
        if (picked.length === 0) {
            summaryEl.textContent = '还没有选择成员';
        } else {
            const names = picked
                .map((id) => (State.contacts || []).find((c) => String(c?.id || '') === id))
                .filter(Boolean)
                .slice(0, 3)
                .map((contact) => getContactDisplayName(contact));
            summaryEl.textContent = picked.length <= 3 ? `已选择：${names.join('、')}` : `已选择 ${picked.length} 位成员`;
        }
    }
    if (stripEl) {
        stripEl.innerHTML = '';
        stripEl.style.display = 'none';
    }
    document.querySelectorAll('#group-create-member-list .group-create-member-item').forEach((item) => {
        const id = String(item.getAttribute('data-contact-id') || '').trim();
        item.classList.toggle('is-selected', groupCreateDraftSelectedIds.has(id));
    });
}

function renderGroupCreateMemberList() {
    const list = document.getElementById('group-create-member-list');
    if (!list) return;
    const keyword = String(document.getElementById('group-create-search')?.value || '').trim().toLowerCase();
    const prevPicked = new Set(getGroupCreateSelectedIds());
    list.innerHTML = '';
    const filteredContacts = (State.contacts || []).filter((contact) => {
        if (!keyword) return true;
        const haystack = [
            getContactDisplayName(contact),
            String(contact?.name || ''),
            String(contact?.remarkName || ''),
            String(contact?.style || '')
        ].join('\n').toLowerCase();
        return haystack.includes(keyword);
    });
    filteredContacts.forEach((contact) => {
        const item = document.createElement('button');
        const contactId = String(contact.id || '').trim();
        item.className = 'group-create-member-item';
        item.type = 'button';
        item.setAttribute('data-contact-id', contactId);
        item.setAttribute('aria-pressed', prevPicked.has(contactId) ? 'true' : 'false');
        item.innerHTML = `
            <div class="group-create-member-avatar">${getAvatarHtml(contact.avatar)}</div>
            <div class="group-create-member-name">${escapeHtml(getContactDisplayName(contact))}</div>
            <div class="group-create-member-checkmark" aria-hidden="true">
                <i class="fas fa-check"></i>
            </div>
        `;
        item.addEventListener('click', () => {
            if (groupCreateDraftSelectedIds.has(contactId)) groupCreateDraftSelectedIds.delete(contactId);
            else groupCreateDraftSelectedIds.add(contactId);
            item.setAttribute('aria-pressed', groupCreateDraftSelectedIds.has(contactId) ? 'true' : 'false');
            updateGroupCreateSelectionUi();
        });
        list.appendChild(item);
    });
    if (!filteredContacts.length) {
        list.innerHTML = `<div class="group-create-empty">${keyword ? '没有搜到这个好友' : '还没有可选好友'}</div>`;
    }
    updateGroupCreateSelectionUi();
}

function openGroupListPage() {
    renderGroupSessionsList();
    showPage('group-list-page');
}

function resetGroupCreateForm() {
    const nameEl = document.getElementById('group-create-name');
    const avatarEl = document.getElementById('group-create-avatar');
    const searchEl = document.getElementById('group-create-search');
    groupCreateDraftSelectedIds = new Set();
    if (nameEl) nameEl.value = '';
    if (avatarEl) avatarEl.value = '';
    if (searchEl) searchEl.value = '';
    renderGroupCreateMemberList();
}

function openGroupCreatePage() {
    resetGroupCreateForm();
    showPage('group-create-page');
}

function createGroupSessionFromForm() {
    const nameEl = document.getElementById('group-create-name');
    const avatarEl = document.getElementById('group-create-avatar');
    const checked = getGroupCreateSelectedIds();
    if (checked.length < 2) {
        showToast('至少选择 2 个联系人');
        return null;
    }
    const session = {
        id: `group_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
        type: 'group',
        contactId: '',
        name: String(nameEl?.value || '').trim() || `${getContactDisplayName(State.contacts.find(c => c.id === checked[0]))}等${checked.length}人`,
        avatar: String(avatarEl?.value || '').trim() || 'group',
        memberIds: checked,
        ownerId: 'me',
        announcement: '',
        allowOfflineSameLocation: false,
        muteNotifications: false,
        isPinned: false,
        unreadCount: 0,
        lastMessage: '群聊已创建',
        lastTime: '',
        lastActiveAt: Date.now(),
        chatBackground: null,
        replyCursor: 0
    };
    State.sessions.push(session);
    State.chatHistories[session.id] = [{
        role: 'system',
        content: `你创建了群聊「${session.name}」`,
        time: Date.now()
    }];
    updateSessionPreview(session.id, '群聊已创建');
    Storage.saveSessions(State.sessions);
    Storage.saveChatHistories(State.chatHistories);
    initContactsList();
    initChatList();
    return session;
}

function hydrateGroupChatMorePage(session) {
    if (!isGroupSession(session)) return;
    const membersEl = document.getElementById('group-chatinfo-members');
    const avatarTextEl = document.getElementById('group-chatinfo-avatar-text');
    const nameEl = document.getElementById('group-chatinfo-name');
    const announcementEl = document.getElementById('group-chatinfo-announcement');
    const contextLimitEl = document.getElementById('group-chat-context-limit-text');
    const offlineModeTextEl = document.getElementById('group-chat-offline-mode-text');
    const offlineSameLocationToggle = document.getElementById('group-chat-offline-same-location-toggle');
    const muteToggle = document.getElementById('group-chat-mute-toggle');
    const pinToggle = document.getElementById('group-chat-pin-toggle');
    const manualSummaryCountEl = document.getElementById('group-chat-manual-summary-count');
    const manualSummaryHintEl = document.getElementById('group-chat-manual-summary-hint');
    const manualSummaryStartEl = document.getElementById('group-chat-manual-summary-start');
    const manualSummaryEndEl = document.getElementById('group-chat-manual-summary-end');
    if (avatarTextEl) avatarTextEl.textContent = getSessionAvatar(session) ? '已设置' : '修改';
    if (nameEl) nameEl.textContent = getSessionDisplayName(session);
    if (announcementEl) announcementEl.textContent = String(session.announcement || '').trim() || '暂无';
    if (contextLimitEl) {
        const sessionLimit = Math.max(0, parseInt(session.groupContextLimit ?? 0, 10) || 0);
        contextLimitEl.textContent = sessionLimit > 0
            ? `${sessionLimit} 条`
            : '跟随角色设置';
    }
    if (offlineModeTextEl) {
        offlineModeTextEl.textContent = getOfflineModeStatusText(getGroupOfflineModeConfig(session));
    }
    if (offlineSameLocationToggle) offlineSameLocationToggle.classList.toggle('active', !!session.allowOfflineSameLocation);
    if (muteToggle) muteToggle.classList.toggle('active', !!session.muteNotifications);
    if (pinToggle) pinToggle.classList.toggle('active', !!session.isPinned);
    const summaryStats = getSummaryMessageStats(session.id);
    const messageCount = summaryStats.totalCount;
    if (manualSummaryCountEl) manualSummaryCountEl.textContent = `当前共 ${messageCount} 条对话，已总结 ${summaryStats.summarizedCount} 条`;
    if (manualSummaryHintEl) {
        manualSummaryHintEl.textContent = messageCount > 0
            ? `按群聊消息条数编号，包含起止；未总结 ${summaryStats.unsummarizedCount} 条，自动总结不会重复处理已总结部分`
            : '当前群聊还没有可总结的消息';
    }
    if (manualSummaryStartEl) {
        manualSummaryStartEl.max = String(Math.max(1, messageCount));
        if (messageCount <= 0) manualSummaryStartEl.value = '';
        else if (!manualSummaryStartEl.value || Number(manualSummaryStartEl.value) > messageCount) manualSummaryStartEl.value = '1';
    }
    if (manualSummaryEndEl) {
        manualSummaryEndEl.max = String(Math.max(1, messageCount));
        if (messageCount <= 0) manualSummaryEndEl.value = '';
        else if (!manualSummaryEndEl.value || Number(manualSummaryEndEl.value) > messageCount) manualSummaryEndEl.value = String(messageCount);
    }
    if (membersEl) {
        const members = getGroupMemberContacts(session);
        const userProfile = getUserProfileForContact();
        membersEl.innerHTML = `
            <div class="chatinfo-member">
                <div class="chatinfo-avatar">${getAvatarHtml(userProfile.avatar)}</div>
                <div class="chatinfo-name">${escapeHtml(userProfile.nickname || '我')}</div>
            </div>
            ${members.map((member) => `
                <div class="chatinfo-member">
                    <div class="chatinfo-avatar">${getAvatarHtml(member.avatar)}</div>
                    <div class="chatinfo-name">${escapeHtml(getContactDisplayName(member))}</div>
                </div>
            `).join('')}
        `;
    }
    updateManualSummaryActionUi(session.id);
}

function getLatestGroupUserTriggerText(session) {
    const history = getSessionHistory(session?.id).slice().reverse();
    const lastUserMessage = history.find((msg) => msg?.role === 'user');
    return lastUserMessage ? toPlainTextFromStoredContent(lastUserMessage.content) : '';
}

function getGroupMemberMentionAliases(member) {
    const name = String(getContactDisplayName(member) || '').trim();
    const rawName = String(member?.name || '').trim();
    const remarkName = String(member?.remarkName || '').trim();
    return Array.from(new Set([
        name ? `@${name}` : '',
        name ? `＠${name}` : '',
        name,
        rawName ? `@${rawName}` : '',
        rawName ? `＠${rawName}` : '',
        rawName,
        remarkName ? `@${remarkName}` : '',
        remarkName ? `＠${remarkName}` : '',
        remarkName
    ].filter(Boolean)));
}

function getMentionedGroupMembers(session, userText = '') {
    const members = getGroupMemberContacts(session);
    const text = String(userText || '').trim();
    if (!text) return [];
    return members
        .map((member) => {
            const aliases = getGroupMemberMentionAliases(member);
            let matchedIndex = -1;
            aliases.forEach((alias) => {
                const idx = text.indexOf(alias);
                if (idx >= 0 && (matchedIndex < 0 || idx < matchedIndex)) matchedIndex = idx;
            });
            return matchedIndex >= 0 ? { member, matchedIndex } : null;
        })
        .filter(Boolean)
        .sort((a, b) => a.matchedIndex - b.matchedIndex)
        .map((item) => item.member);
}

function getOrderedGroupReplyMembers(session, userText = '') {
    const members = getGroupMemberContacts(session);
    if (members.length === 0) return [];
    const cursor = Math.max(0, parseInt(session.replyCursor ?? 0, 10) || 0);
    const rotated = members.map((_, idx) => members[(cursor + idx) % members.length]);
    const mentioned = getMentionedGroupMembers(session, userText);
    const mentionedIds = new Set(mentioned.map((member) => String(member?.id || '')));
    const ordered = [
        ...mentioned,
        ...rotated.filter((member) => !mentionedIds.has(String(member?.id || '')))
    ];
    session.replyCursor = (cursor + 1) % Math.max(1, members.length);
    Storage.saveSessions(State.sessions);
    return ordered;
}

async function runGroupAiReply(session, options = {}) {
    if (!isGroupSession(session)) return;
    const sid = String(session.id || '');
    if (!sid) return;
    if (isAiRunningForSession(sid)) {
        showToast('正在生成中...');
        return;
    }
    const controller = new AbortController();
    const triggerText = String(options.userText || '').trim() || getLatestGroupUserTriggerText(session);
    const orderedMembers = getOrderedGroupReplyMembers(session, triggerText);
    if (orderedMembers.length === 0) {
        showToast('群里还没有可回复的成员');
        return;
    }
    const mentionedMembers = getMentionedGroupMembers(session, triggerText);
    const mentionedMemberIds = mentionedMembers.map((member) => String(member?.id || ''));
    setAiTaskForSession(sid, controller, { kind: 'group' });
    try {
        delete State.aiInterrupted[sid];
        const respondedMemberIds = [];
        const traceBlocks = [];
        for (let i = 0; i < orderedMembers.length; i++) {
            const member = orderedMembers[i];
            const memberHistory = getGroupAiVisibleHistory(session, member);
            const recallQueryText = buildMemoryRecallQueryText(memberHistory, triggerText);
            const recalledSummaryText = await recallSummaryChunks(session, recallQueryText, 2);
            const promptBundle = buildGroupReplyPromptBundle(session, member, {
                history: memberHistory,
                triggerText,
                summaryMemoryText: recalledSummaryText,
                mentionedMemberIds,
                respondedMemberIds: respondedMemberIds.slice(),
                participantIndex: i,
                participantTotal: orderedMembers.length
            });
            traceBlocks.push(`【群成员：${getContactDisplayName(member)}】\n${promptBundle.traceText}`);
            await fetchGroupAIResponse(session, member, {
                signal: controller.signal,
                triggerText,
                mentionedMemberIds,
                respondedMemberIds: respondedMemberIds.slice(),
                participantIndex: i,
                participantTotal: orderedMembers.length,
                promptBundle
            });
            respondedMemberIds.push(String(member?.id || ''));
        }
        if (traceBlocks.length > 0) {
            rememberPromptTrace(session.id, 'chat', traceBlocks.join('\n\n'), { label: '群聊互动' });
        }
        maybeQueueAutoSummaryForTarget(session);
    } catch (e) {
        const isAbort = e && (e.name === 'AbortError' || String(e.message || '').toLowerCase().includes('aborted'));
        if (isAbort) {
            State.aiInterrupted[sid] = true;
            if (String(State.currentSessionId || '') === sid) showToast('已中断');
            return;
        }
        throw e;
    } finally {
        clearAiTaskForSession(sid, controller);
        if (String(State.currentSessionId || '') === String(session.id || '')) {
            hideTypingIndicator();
            clearAssistantTypingBubble();
        }
    }
}

async function fetchGroupAIResponse(session, member, options = {}) {
    const currentApiConfig = State.apiConfigs.find(c => c.id === State.currentApiId);
    const useProxy = !!currentApiConfig?.useProxy;
    const targetUrl = useProxy ? String(currentApiConfig?.proxyUrl || '').trim() : normalizeChatCompletionsUrl(String(currentApiConfig?.apiUrl || '').trim());
    const apiKey = String(currentApiConfig?.apiKey || '').trim();
    if (!currentApiConfig || !targetUrl || (!useProxy && !apiKey)) {
        throw new Error('API未配置');
    }
    const promptBundle = options.promptBundle || buildGroupReplyPromptBundle(session, member, options);
    const systemPrompt = promptBundle.systemPrompt;
    const userPrompt = promptBundle.userPrompt;
    State.lastSentSystemPrompt[session.id] = systemPrompt;
    if (!State.lastStickerPromptCandidates) State.lastStickerPromptCandidates = {};
    State.lastStickerPromptCandidates[String(member?.id || '')] = Array.isArray(promptBundle.stickerCandidates) ? promptBundle.stickerCandidates : [];
    const payload = {
        model: String(currentApiConfig.model || '').trim() || 'gpt-3.5-turbo',
        messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt }
        ]
    };
    const headers = { 'Content-Type': 'application/json' };
    if (!useProxy) headers.Authorization = `Bearer ${apiKey}`;
    if (String(State.currentSessionId || '') === String(session.id || '')) {
        setTypingIndicator(`${getContactDisplayName(member)} 正在输入...`);
    }
    try {
        const response = await fetch(targetUrl, {
            method: 'POST',
            headers,
            signal: options.signal,
            body: JSON.stringify(payload)
        });
        if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
        }
        const data = await response.json();
        const reply = String(
            data?.choices?.[0]?.message?.content
            || data?.choices?.[0]?.text
            || data?.message?.content
            || data?.output_text
            || data?.result
            || ''
        ).trim();
        const cleanedReply = reply.replace(/^```json\s*/, '').replace(/```\s*$/, '');
        let output = [];
        let parsedArrayHandled = false;
        const canRetryNoReply = !options.__noReplyRetried;
        try {
            const parsed = JSON.parse(cleanedReply);
            if (Array.isArray(parsed)) {
                parsedArrayHandled = true;
                let parsedArr = normalizeQuoteMessagesInPayload(
                    normalizePseudoMediaMessagesInPayload(
                        normalizeStickerMessagesInPayload(parsed.slice(), member.id)
                    ),
                    session.id
                );
                let visibleItems = parsedArr.filter((item) => !(item && typeof item === 'object' && item.type === 'thought_state'));
                const isNoReply = visibleItems.length === 1
                    && visibleItems[0]
                    && typeof visibleItems[0] === 'object'
                    && visibleItems[0].type === 'action'
                    && String(visibleItems[0].command || '').toUpperCase() === 'NO_REPLY';
                if (isNoReply) {
                    const nowTs = Date.now();
                    const cooldownMin = Math.max(1, Math.min(120, parseInt(member?.noReplyCooldownMin ?? 10, 10) || 10));
                    const cooldownMs = cooldownMin * 60 * 1000;
                    const lastNoReplyAt = Number(member?.lastNoReplyAt || 0) || 0;
                    const inCooldown = lastNoReplyAt && (nowTs - lastNoReplyAt) < cooldownMs;
                    if (!member?.allowSeenNoReply || inCooldown) {
                        if (canRetryNoReply) {
                            const retryOptions = { ...options, __noReplyRetried: true, forceReply: true };
                            delete retryOptions.promptBundle;
                            return fetchGroupAIResponse(session, member, retryOptions);
                        }
                        member.lastActiveAt = nowTs;
                        Storage.saveContacts(State.contacts);
                        return;
                    }
                    member.lastNoReplyAt = nowTs;
                    member.lastActiveAt = nowTs;
                    Storage.saveContacts(State.contacts);
                    return;
                }
                const actionItems = parsedArr.filter((item) => item && typeof item === 'object' && item.type === 'action');
                for (const act of actionItems) {
                    const cmd = String(act.command || '').toUpperCase();
                    if (cmd === 'WX_MONEY_ACCEPT') {
                        if (options.allowMoneyActions === false) continue;
                        const kind = String(act.kind || '').toLowerCase();
                        if (kind !== 'transfer' && kind !== 'redpacket') continue;
                        const updated = markOutgoingWxMoneyAccepted(session.id, kind, {
                            actorName: getContactDisplayName(member)
                        });
                        if (!updated) continue;
                        if (!parsedArr.some((x) => x && typeof x === 'object' && (x.type === 'text' || x.type === 'text_message') && typeof x.content === 'string' && x.content.trim())) {
                            parsedArr.unshift({
                                type: 'text',
                                content: kind === 'transfer' ? '我收到了。' : '我领到啦。'
                            });
                        }
                    } else if (cmd === 'WX_PAT') {
                        if (member.aiPatEnabled === false) continue;
                        triggerPatEvent(member, 'assistant', {
                            historyId: session.id,
                            displayName: getContactDisplayName(member),
                            target: session
                        });
                    } else if (cmd === 'WX_RECALL_LAST') {
                        if (member.aiRecallEnabled === false) continue;
                        recallLatestGroupMessageBySender(session.id, member.id, {
                            actorLabel: getContactDisplayName(member)
                        });
                    } else if (cmd === 'WX_RECALL_OFFSET') {
                        if (member.aiRecallEnabled === false) continue;
                        const offset = act.offsetFromLast ?? act.offset ?? 0;
                        recallGroupMessageBySenderOffset(session.id, member.id, offset, {
                            actorLabel: getContactDisplayName(member)
                        });
                    } else if (cmd === 'WX_CALL_START') {
                        const callType = String(act.callType || '').toLowerCase();
                        if (callType === 'voice' || callType === 'video') {
                            startIncomingCallFromGroupMember(session, member, callType);
                            if (!parsedArr.some((x) => x && typeof x === 'object' && (x.type === 'text' || x.type === 'text_message') && typeof x.content === 'string' && x.content.trim())) {
                                parsedArr.unshift({
                                    type: 'text',
                                    content: callType === 'video' ? '我给你打个视频。' : '我给你打个语音。'
                                });
                            }
                        }
                    } else if (cmd === 'WX_REMARK_SET') {
                        applyGroupRemarkSet(session, member, act);
                    } else if (cmd === 'WX_AVATAR_SET') {
                        applyGroupAvatarSet(session, member, act);
                    }
                }
                visibleItems = parsedArr.filter((item) => !(item && typeof item === 'object' && item.type === 'thought_state'));
                output = expandAiDisplayItems(
                    visibleItems.filter((item) => !(item && typeof item === 'object' && item.type === 'action')),
                    { maxLen: 22, maxItems: 10, maxItemsTotal: 20 }
                );
            }
        } catch (err) {
        }
        if (output.length === 0 && parsedArrayHandled) {
            return;
        }
        if (output.length === 0) {
            const list = splitAiTextToBubbles(cleanedReply, { maxLen: 24, maxItems: 4 }).filter(Boolean);
            output = list.length > 0 ? list.map((line) => ({ type: 'text', content: line })) : [{ type: 'text', content: '收到' }];
        }
        if (!State.chatHistories[session.id]) State.chatHistories[session.id] = [];
        const baseTs = Date.now();
        output.forEach((item, idx) => {
            const stored = (item && typeof item === 'object')
                ? JSON.stringify(item)
                : JSON.stringify({ type: 'text', content: String(item || '') });
            State.chatHistories[session.id].push({
                role: 'assistant',
                content: stored,
                time: baseTs + idx,
                senderId: member.id
            });
        });
        Storage.saveChatHistories(State.chatHistories);
        const lastItem = output[output.length - 1];
        const previewText = (() => {
            if (lastItem && typeof lastItem === 'object') {
                if (lastItem.type === 'text' || lastItem.type === 'text_message') return String(lastItem.content || '').trim() || '[消息]';
                if (lastItem.type === 'sticker_message') return '[表情]';
                if (lastItem.type === 'image') return '[图片]';
                if (lastItem.type === 'voice') return '[语音]';
                if (lastItem.type === 'quote' || lastItem.type === 'quote_reply') return '[引用]';
            }
            return typeof lastItem === 'string' ? lastItem : '[消息]';
        })();
        updateSessionPreview(session.id, `${getContactDisplayName(member)}：${previewText}`, baseTs);
        registerIncomingGroupMessages(session, output.length);
        initChatList();
        renderGroupSessionsList();
        if (String(State.currentSessionId || '') === String(session.id || '')) {
            renderChatMessages();
        }
    } finally {
        if (String(State.currentSessionId || '') === String(session.id || '')) {
            hideTypingIndicator();
            clearAssistantTypingBubble();
        }
    }
}

function renderApiConfigSelect() {
    const select = document.getElementById('api-config-select');
    if (!select) return;
    select.innerHTML = '';
    State.apiConfigs.forEach(config => {
        const option = document.createElement('option');
        option.value = config.id;
        option.textContent = config.name || '未命名方案';
        if (config.id === State.currentApiId) {
            option.selected = true;
            // 同步更新输入框
            document.getElementById('api-name-input').value = config.name || '';
            document.getElementById('api-url-input').value = config.apiUrl || '';
            document.getElementById('api-key-input').value = config.apiKey || '';
            setApiProxyUIFromConfig(config);
            applyApiModelUIFromConfig(config);
            applyApiVisionUIFromConfig(config);
            applyApiStreamUIFromConfig(config);
        }
        select.appendChild(option);
    });
}

function renderSharedMainApiSelect(selectEl, selectedId) {
    if (!selectEl) return;
    const picked = String(selectedId || '').trim() || 'current';
    selectEl.innerHTML = '';
    const followOpt = document.createElement('option');
    followOpt.value = 'current';
    followOpt.textContent = '跟随当前方案';
    selectEl.appendChild(followOpt);
    (State.apiConfigs || []).forEach((cfg) => {
        if (!cfg) return;
        const opt = document.createElement('option');
        opt.value = String(cfg.id || '');
        opt.textContent = String(cfg.name || '未命名方案');
        selectEl.appendChild(opt);
    });
    selectEl.value = picked;
    if (!selectEl.value) selectEl.value = 'current';
}

function getMainApiConfigBySharedId(sharedId) {
    const id = String(sharedId || '').trim() || 'current';
    const targetId = (id === 'current') ? State.currentApiId : id;
    return (State.apiConfigs || []).find(c => String(c?.id || '') === String(targetId || ''));
}

function resolveChatApiRuntimeFromConfigLike(cfgLike, modelOverride) {
    const useProxy = !!cfgLike?.useProxy;
    const targetUrl = useProxy ? String(cfgLike?.proxyUrl || '').trim() : normalizeChatCompletionsUrl(String(cfgLike?.apiUrl || '').trim());
    const apiKey = String(cfgLike?.apiKey || '').trim();
    const modelFromCfg = getCurrentModelForConfig(cfgLike);
    const model = String(modelOverride || '').trim() || String(modelFromCfg || '').trim() || 'gpt-3.5-turbo';
    return { useProxy, targetUrl, apiKey, model };
}

function normalizeChatCompletionsUrl(rawUrl) {
    const input = (rawUrl || '').trim();
    if (!input) return '';
    try {
        const url = new URL(input);
        const path = url.pathname.replace(/\/+$/, '');
        if (/\/chat\/completions$/i.test(path)) {
            url.pathname = path;
            return url.toString();
        }
        if (/\/v1$/i.test(path)) {
            url.pathname = `${path}/chat/completions`;
            return url.toString();
        }
        url.pathname = `${path}/v1/chat/completions`;
        return url.toString();
    } catch (e) {
        return input;
    }
}

function normalizeModelsUrlFromChatUrl(rawUrl) {
    const input = (rawUrl || '').trim();
    if (!input) return '';
    try {
        const url = new URL(input);
        let path = url.pathname.replace(/\/+$/, '');
        path = path.replace(/\/v1\/chat\/completions$/i, '');
        path = path.replace(/\/chat\/completions$/i, '');
        path = path.replace(/\/v1\/embeddings$/i, '');
        path = path.replace(/\/embeddings$/i, '');
        path = path.replace(/\/v1$/i, '');
        url.pathname = `${path}/v1/models`;
        return url.toString();
    } catch (e) {
        return input;
    }
}

function normalizeEmbeddingsUrl(rawUrl) {
    const input = (rawUrl || '').trim();
    if (!input) return '';
    try {
        const url = new URL(input);
        const path = url.pathname.replace(/\/+$/, '');
        if (/\/embeddings$/i.test(path)) {
            url.pathname = path;
            return url.toString();
        }
        if (/\/chat\/completions$/i.test(path)) {
            url.pathname = path.replace(/\/chat\/completions$/i, '/embeddings');
            return url.toString();
        }
        if (/\/v1$/i.test(path)) {
            url.pathname = `${path}/embeddings`;
            return url.toString();
        }
        url.pathname = `${path}/v1/embeddings`;
        return url.toString();
    } catch (e) {
        return input;
    }
}

function getLatestSummaryText(contactId) {
    const id = String(contactId || '').trim();
    if (!id) return '';
    const mega = getLatestMegaSummary(contactId);
    const pendingMini = getPendingMiniSummaries(contactId);
    const parts = [];
    if (mega?.content) parts.push(`【长期总记忆】\n${String(mega.content).trim()}`);
    if (pendingMini.length > 0) {
        parts.push([
            '【最近阶段记事】',
            pendingMini.map((item, index) => `第 ${index + 1} 条小总结：\n${String(item.content || '').trim()}`).join('\n\n')
        ].join('\n'));
    }
    return parts.join('\n\n').trim();
}

function getSummaryVectorId(summary) {
    if (summary?.id) return String(summary.id);
    const time = summary?.time ? String(summary.time) : '';
    const content = typeof summary?.content === 'string' ? summary.content : '';
    return `${summary?.kind || 'mini'}_${time}_${hashString32(content)}`;
}

function createSummaryItemId(kind = 'mini') {
    return `${kind}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

function ensureSummaryStore(contactId) {
    const id = String(contactId || '').trim();
    if (!id) return createEmptyContactSummaryStore();
    if (!State.summaryHistories) State.summaryHistories = {};
    State.summaryHistories[id] = normalizeContactSummaryStore(State.summaryHistories[id]);
    return State.summaryHistories[id];
}

function getMiniSummaryList(contactId) {
    return ensureSummaryStore(contactId).mini;
}

function getMegaSummaryList(contactId) {
    return ensureSummaryStore(contactId).mega;
}

function getLatestMegaSummary(contactId) {
    const list = getMegaSummaryList(contactId);
    return list.length > 0 ? list[list.length - 1] : null;
}

function getPendingMiniSummaries(contactId) {
    return getMiniSummaryList(contactId).filter((item) => !String(item?.mergedMegaId || '').trim());
}

function removeSummaryVectorsByItems(contactId, items) {
    const id = String(contactId || '').trim();
    if (!id || !Array.isArray(items) || items.length === 0) return;
    const store = State.summaryVectors?.[id];
    if (!store?.items || typeof store.items !== 'object') return;
    const removedIds = new Set(items.map(getSummaryVectorId).filter(Boolean));
    if (removedIds.size === 0) return;
    Object.keys(store.items).forEach((key) => {
        const parentId = String(store.items[key]?.parentId || '');
        if (removedIds.has(parentId) || removedIds.has(key) || Array.from(removedIds).some((sid) => key.startsWith(`${sid}#`))) {
            delete store.items[key];
        }
    });
    Storage.saveSummaryVectors(State.summaryVectors);
}

function saveMiniSummaryItem(contactId, summaryItem) {
    const id = String(contactId || '').trim();
    if (!id || !summaryItem || typeof summaryItem !== 'object') return;
    const store = ensureSummaryStore(id);
    const item = normalizeSummaryItem({ ...summaryItem, kind: 'mini', id: summaryItem.id || createSummaryItemId('mini') }, 'mini');
    store.mini.push(item);
    Storage.saveSummaryHistories(State.summaryHistories);
}

function saveMegaSummaryItem(contactId, summaryItem, sourceMiniIds = []) {
    const id = String(contactId || '').trim();
    if (!id || !summaryItem || typeof summaryItem !== 'object') return null;
    const store = ensureSummaryStore(id);
    const mergedMiniItems = store.mini.filter((mini) => (Array.isArray(sourceMiniIds) ? sourceMiniIds : []).includes(mini.id));
    const item = normalizeSummaryItem({
        ...summaryItem,
        kind: 'mega',
        id: summaryItem.id || createSummaryItemId('mega'),
        sourceSummaryIds: sourceMiniIds
    }, 'mega');
    const oldMegaItems = store.mega.slice();
    const pickedIds = new Set((Array.isArray(sourceMiniIds) ? sourceMiniIds : []).map((sid) => String(sid || '').trim()).filter(Boolean));
    store.mini = store.mini.map((mini) => pickedIds.has(String(mini.id || '').trim()) ? { ...mini, mergedMegaId: item.id } : mini);
    store.mega.push(item);
    Storage.saveSummaryHistories(State.summaryHistories);
    removeSummaryVectorsByItems(id, mergedMiniItems);
    removeSummaryVectorsByItems(id, oldMegaItems);
    return item;
}

function saveManualSummaryItem(contactId, summaryItem) {
    saveMiniSummaryItem(contactId, { ...summaryItem, source: summaryItem?.source || 'manual' });
}

function saveAutoSummaryItem(contactId, summaryItem) {
    saveMiniSummaryItem(contactId, { ...summaryItem, source: summaryItem?.source || 'auto' });
}

function isArchivedForAiMessage(message) {
    if (!message) return false;
    if (message.role === 'system' && String(message.content || '').startsWith('[系统归档记忆]')) return true;
    return !!message.archivedForAi;
}

function getAiVisibleHistory(contactId) {
    const id = String(contactId || '').trim();
    if (!id) return [];
    normalizeAssistantHistoryToPerBubble(id);
    const history = Array.isArray(State.chatHistories?.[id]) ? State.chatHistories[id] : [];
    return history.filter((item) => item && !isArchivedForAiMessage(item));
}

function getSummarizableChatMessages(contactId, options = {}) {
    const id = String(contactId || '').trim();
    if (!id) return [];
    normalizeAssistantHistoryToPerBubble(id);
    const history = Array.isArray(State.chatHistories?.[id]) ? State.chatHistories[id] : [];
    const includeArchived = options.includeArchived !== false;
    const withIndexes = !!options.withIndexes;
    const withPositions = !!options.withPositions;
    const withSourceKeys = !!options.withSourceKeys;
    const result = [];
    let summaryIndex = 0;
    history.forEach((item, index) => {
        if (!item || (item.role !== 'user' && item.role !== 'assistant')) return;
        if (!includeArchived && isArchivedForAiMessage(item)) return;
        summaryIndex += 1;
        if (!withIndexes && !withPositions && !withSourceKeys) {
            result.push(item);
            return;
        }
        const next = { ...item };
        if (withIndexes) next._historyIndex = index;
        if (withPositions) next._summaryIndex = summaryIndex;
        if (withSourceKeys) next._sourceKey = buildMessageSourceKey(item);
        result.push(next);
    });
    return result;
}

function getSummaryCoveredMessageKeys(contactId, allMessages = null) {
    const id = String(contactId || '').trim();
    if (!id) return new Set();
    const messages = Array.isArray(allMessages)
        ? allMessages
        : getSummarizableChatMessages(id, { includeArchived: true, withSourceKeys: true, withPositions: true });
    const coveredKeys = new Set();

    messages.forEach((item) => {
        const key = String(item?._sourceKey || buildMessageSourceKey(item) || '').trim();
        if (!key) return;
        if (isArchivedForAiMessage(item) || String(item?.summaryMiniId || '').trim()) {
            coveredKeys.add(key);
        }
    });

    getMiniSummaryList(id).forEach((item) => {
        const storedKeys = Array.isArray(item?.sourceMessageKeys)
            ? item.sourceMessageKeys.map((key) => String(key || '').trim()).filter(Boolean)
            : [];
        if (storedKeys.length > 0) {
            storedKeys.forEach((key) => coveredKeys.add(key));
            return;
        }
        const start = Math.max(1, parseInt(item?.rangeStart ?? 0, 10) || 0);
        const end = Math.max(start, parseInt(item?.rangeEnd ?? 0, 10) || 0);
        if (!start || !end) return;
        messages.slice(start - 1, end).forEach((message) => {
            const key = String(message?._sourceKey || buildMessageSourceKey(message) || '').trim();
            if (key) coveredKeys.add(key);
        });
    });

    return coveredKeys;
}

function getSummaryMessageStats(contactId) {
    const messages = getSummarizableChatMessages(contactId, { includeArchived: true, withSourceKeys: true, withPositions: true });
    const coveredKeys = getSummaryCoveredMessageKeys(contactId, messages);
    let summarizedCount = 0;
    messages.forEach((item) => {
        const key = String(item?._sourceKey || buildMessageSourceKey(item) || '').trim();
        if (key && coveredKeys.has(key)) summarizedCount += 1;
    });
    const totalCount = messages.length;
    const safeSummarized = Math.min(totalCount, summarizedCount);
    return {
        totalCount,
        summarizedCount: safeSummarized,
        unsummarizedCount: Math.max(0, totalCount - safeSummarized),
        coveredKeys
    };
}

function getAutoSummaryCandidateMessages(contactId, options = {}) {
    const visibleMessages = getSummarizableChatMessages(contactId, {
        includeArchived: false,
        withIndexes: !!options.withIndexes,
        withPositions: !!options.withPositions,
        withSourceKeys: true
    });
    const coveredKeys = getSummaryCoveredMessageKeys(contactId);
    return visibleMessages
        .filter((item) => {
            const key = String(item?._sourceKey || buildMessageSourceKey(item) || '').trim();
            return !key || !coveredKeys.has(key);
        })
        .map((item) => {
            if (options.withSourceKeys) return item;
            const next = { ...item };
            delete next._sourceKey;
            return next;
        });
}

function getSummaryRuntimeConfig() {
    const config = State.summaryConfig || Storage.getSummaryConfig();
    const useMain = !!config?.useMainApi;
    const baseCfg = useMain
        ? getMainApiConfigBySharedId(config?.mainApiId)
        : { useProxy: false, apiUrl: config?.apiUrl || '', apiKey: config?.apiKey || '' };
    return {
        config,
        runtime: baseCfg ? resolveChatApiRuntimeFromConfigLike(baseCfg, config?.model) : null
    };
}

function buildSummaryTextBatches(messages, options = {}) {
    const list = Array.isArray(messages) ? messages : [];
    const maxChars = Math.max(1200, Math.min(24000, parseInt(options.maxChars ?? 7000, 10) || 7000));
    const maxUnits = Math.max(10, Math.min(160, parseInt(options.maxUnits ?? 70, 10) || 70));
    const target = options.target || resolveTargetEntityById(options.targetId, options.targetType);
    const isGroupTarget = isGroupSession(target);
    const userProfile = getUserProfileForContact(target);
    const groupMembers = isGroupTarget ? getGroupMemberContacts(target) : [];
    const batches = [];
    let currentLines = [];
    let currentChars = 0;
    let currentUnits = 0;
    const pushCurrent = () => {
        if (currentLines.length === 0) return;
        batches.push(currentLines.join('\n'));
        currentLines = [];
        currentChars = 0;
        currentUnits = 0;
    };
    list.forEach((m) => {
        if (!m) return;
        const timestamp = Number(m.time || 0) > 0 ? formatWxCNTime(m.time) : '';
        let speaker = m.role;
        if (m.role === 'user') {
            speaker = userProfile.nickname || '我';
        } else if (m.role === 'assistant') {
            if (isGroupTarget) {
                const sender = findGroupMemberFromList(m.senderId, groupMembers)
                    || (State.contacts || []).find((item) => String(item?.id || '') === String(m.senderId || ''));
                speaker = getContactDisplayName(sender);
            } else {
                speaker = getEntityDisplayName(target || { name: '对方' });
            }
        }
        const prefix = timestamp ? `[${timestamp}]` : '';
        const line = `${prefix}[${speaker || m.role}]: ${toPlainTextFromStoredContent(m.content)}`.trim();
        if (!line) return;
        const unitCount = Math.max(1, getStoredMessageUnitCount(m.content));
        const safeLine = line.length > maxChars ? `${line.slice(0, maxChars - 1)}…` : line;
        const nextChars = currentChars + (currentLines.length > 0 ? 1 : 0) + safeLine.length;
        if (currentLines.length > 0 && (nextChars > maxChars || currentUnits + unitCount > maxUnits)) {
            pushCurrent();
        }
        currentLines.push(safeLine);
        currentChars += (currentLines.length > 1 ? 1 : 0) + safeLine.length;
        currentUnits += unitCount;
    });
    pushCurrent();
    return batches;
}

function parseSummaryApiError(rawText, status = 0) {
    const raw = String(rawText || '').trim();
    if (!raw) return status ? `接口返回错误（HTTP ${status}）` : '接口返回错误';
    try {
        const parsed = JSON.parse(raw);
        const msg = parsed?.error?.message || parsed?.message || parsed?.detail || parsed?.msg || '';
        if (msg) return String(msg).trim();
    } catch (e) {
    }
    return raw.replace(/\s+/g, ' ').trim().slice(0, 160) || (status ? `接口返回错误（HTTP ${status}）` : '接口返回错误');
}

function formatSummaryFailure(err, fallback = '网络或接口错误') {
    const msg = String(err?.message || '').trim();
    if (!msg || msg === 'SUMMARY_REQUEST_FAILED') return fallback;
    if (msg === 'SUMMARY_CONFIG_INCOMPLETE') return '总结API未配置完整';
    return msg.slice(0, 160);
}

function getSummaryBasePrompt(target, kind = 'mini') {
    const config = State.summaryConfig || Storage.getSummaryConfig();
    const promptText = kind === 'mega'
        ? (config.customPromptMega || Storage.DEFAULT_SUMMARY_MEGA_PROMPT)
        : (config.customPromptMini || config.customPrompt || Storage.DEFAULT_SUMMARY_MINI_PROMPT);
    if (isGroupSession(target)) {
        const session = target;
        const userProfile = getUserProfileForContact();
        const memberList = getGroupMemberContacts(session).map((item) => getContactDisplayName(item)).join('、');
        const vars = {
            ...getScenarioPromptVars({
                name: userProfile.nickname || '我',
                persona: '群聊中的用户本人',
                style: '自然聊天'
            }, {
                char: userProfile.nickname || '我',
                user: getSessionDisplayName(session),
                group_name: getSessionDisplayName(session),
                group_members: memberList || '暂无其他成员',
                summary_kind: kind === 'mega' ? '群聊大总结' : '群聊小总结',
                summary_max_chars: kind === 'mega' ? (config.megaMaxChars || 900) : (config.miniMaxChars || 360),
                mega_trigger_count: config.megaTriggerCount || 10
            })
        };
        return `${renderPromptTemplate(promptText, vars)}

【群聊总结补充规则】
- 这次总结对象是微信群「${getSessionDisplayName(session)}」，不是单聊。
- 以下聊天记录里的“我”统一指用户本人「${userProfile.nickname || '我'}」。
- 群成员名单：${memberList || '暂无其他成员'}。
- assistant 可能对应不同群成员，记录里会标明发言人名字；总结时不要把所有群成员混成一个“对方”。
- 除了用户和群成员各自状态，还要留意群氛围变化、谁更主动、谁爱调侃、谁会吃醋、谁会追问、群里的约定和反复出现的话题。`;
    }
    return renderPromptTemplate(promptText, getScenarioPromptVars(target, {
        summary_kind: kind === 'mega' ? '大总结' : '小总结',
        summary_max_chars: kind === 'mega' ? (config.megaMaxChars || 900) : (config.miniMaxChars || 360),
        mega_trigger_count: config.megaTriggerCount || 10
    }));
}

