    const openIntervalModal = () => {
        if (!State.currentContactId) return;
        const contact = State.contacts.find(c => c.id === State.currentContactId);
        if (!contact) return;
        if (!contact.autoMessageEnabled) return;
        const modal = document.getElementById('chat-auto-interval-modal');
        const input = document.getElementById('chat-auto-interval-input');
        if (input) input.value = String(contact.autoMessageIntervalMin ?? 30);
        modal?.classList.add('show');
    };

    const closeIntervalModal = () => {
        document.getElementById('chat-auto-interval-modal')?.classList.remove('show');
    };

    document.getElementById('chat-auto-message-interval-cell')?.addEventListener('click', openIntervalModal);
    document.getElementById('chat-auto-interval-cancel')?.addEventListener('click', closeIntervalModal);
    document.getElementById('chat-auto-interval-overlay')?.addEventListener('click', closeIntervalModal);
    document.getElementById('chat-auto-interval-confirm')?.addEventListener('click', () => {
        if (!State.currentContactId) return;
        const contact = State.contacts.find(c => c.id === State.currentContactId);
        if (!contact) return;
        const val = parseInt(document.getElementById('chat-auto-interval-input')?.value || '30', 10) || 30;
        contact.autoMessageIntervalMin = Math.max(1, Math.min(1440, val));
        if (contact.autoMessageEnabled) {
            contact.nextAutoMessageAt = Date.now() + contact.autoMessageIntervalMin * 60 * 1000;
        }
        Storage.saveContacts(State.contacts);
        initChatList();
        hydrateChatMorePage(contact);
        closeIntervalModal();
        showToast('已保存');
    });

    document.getElementById('chat-delete-friend-cell')?.addEventListener('click', async () => {
        if (!State.currentContactId) return;
        const contact = State.contacts.find(c => c.id === State.currentContactId);
        if (!contact) return;
        const ok = await WeChatUI.showConfirm('删除好友', `确定删除好友「${contact.name}」吗？聊天记录也将被删除。`, '删除', '取消', true);
        if (!ok) return;
        State.contacts = State.contacts.filter(c => c.id !== contact.id);
        delete State.chatHistories[contact.id];
        Storage.saveContacts(State.contacts);
        Storage.saveChatHistories(State.chatHistories);
        State.currentContactId = null;
        initChatList();
        hardSwitchToMainTab('wechat-tab');
        showToast('已删除');
    });

    document.getElementById('chat-search-cell')?.addEventListener('click', () => {
        if (!State.currentContactId) return;
        const contact = State.contacts.find(c => c.id === State.currentContactId);
        if (!contact) return;
        openChatSearchPage(contact);
    });

    document.getElementById('chat-search-back-btn')?.addEventListener('click', () => {
        hidePage('chat-search-page');
    });
    document.getElementById('chat-search-cancel-btn')?.addEventListener('click', () => {
        const input = document.getElementById('chat-search-input');
        if (input) input.value = '';
        renderChatSearchResults('');
        hidePage('chat-search-page');
    });
    document.getElementById('chat-search-input')?.addEventListener('input', (e) => {
        renderChatSearchResults(e.target.value);
    });

    const chatMessages = document.getElementById('chat-messages');
    if (chatMessages && !chatMessages.dataset.wxMoneyBound) {
        chatMessages.dataset.wxMoneyBound = '1';
        const handleWxMoneyTap = (e) => {
            const node = (e && e.target && e.target.nodeType === 1) ? e.target : e.target?.parentElement;
            const bubble = node?.closest?.('.message-bubble');
            if (!bubble) return;
            const kind = bubble.dataset.wxMoneyKind || '';
            if (!kind) return;
            if (document.getElementById('chat-page')?.classList?.contains('multi-select-mode')) {
                return;
            }
            const suppressUntil = parseInt(bubble.dataset.wxTapSuppressUntil || '0', 10);
            if ((bubble && bubble._longPressFired) || (suppressUntil && Date.now() < suppressUntil)) {
                try { bubble._longPressFired = false; } catch (err) {}
                try { if (e && e.cancelable) e.preventDefault(); } catch (err) {}
                try { e?.stopPropagation?.(); } catch (err) {}
                try { e?.stopImmediatePropagation?.(); } catch (err) {}
                return;
            }
            const side = bubble.dataset.side || (bubble.closest('.message-row')?.classList.contains('right') ? 'right' : 'left');
            const idx = parseInt(bubble.dataset.index || '-1', 10);
            const wxText = bubble.dataset.wxMoneyText || '';
            if (!wxText) return;
            const row = bubble.closest('.message-row');
            const historyId = String(bubble.dataset.historyId || row?.dataset.historyId || getActiveChatId() || '').trim();
            const senderId = String(bubble.dataset.senderId || row?.dataset.senderId || '').trim();
            if (kind === 'redpacket') {
                showRedPacketDetail(wxText, side, Number.isNaN(idx) ? -1 : idx, { historyId, senderId });
            } else if (kind === 'transfer') {
                showTransferDetail(wxText, side, Number.isNaN(idx) ? -1 : idx, { historyId, senderId });
            }
        };
        const handleWxMoneyContextMenu = (e) => {
            const node = (e && e.target && e.target.nodeType === 1) ? e.target : e.target?.parentElement;
            const bubble = node?.closest?.('.message-bubble');
            if (!bubble) return;
            const kind = bubble.dataset.wxMoneyKind || '';
            if (!kind) return;
            const idx = parseInt(bubble.dataset.index || '-1', 10);
            if (!Number.isFinite(idx) || idx < 0) return;
            const side = bubble.dataset.side || (bubble.closest('.message-row')?.classList.contains('right') ? 'right' : 'left');
            try { bubble._longPressFired = true; } catch (err) {}
            try { bubble.dataset.wxTapSuppressUntil = String(Date.now() + 1200); } catch (err) {}
            try { if (e && e.cancelable) e.preventDefault(); } catch (err) {}
            try { e?.stopPropagation?.(); } catch (err) {}
            try { e?.stopImmediatePropagation?.(); } catch (err) {}
            showContextMenu(e, idx, side);
        };
        chatMessages.addEventListener('click', handleWxMoneyTap, true);
        chatMessages.addEventListener('touchend', handleWxMoneyTap, true);
        chatMessages.addEventListener('pointerup', handleWxMoneyTap, true);
        chatMessages.addEventListener('contextmenu', handleWxMoneyContextMenu, true);
    }

    document.getElementById('chat-mute-toggle')?.addEventListener('click', function () {
        if (!State.currentContactId) return;
        const contact = State.contacts.find(c => c.id === State.currentContactId);
        if (!contact) return;
        this.classList.toggle('active');
        contact.muteNotifications = this.classList.contains('active');
        Storage.saveContacts(State.contacts);
        showToast(contact.muteNotifications ? '已开启免打扰' : '已关闭免打扰');
    });

    document.getElementById('chat-pin-toggle')?.addEventListener('click', function () {
        if (!State.currentContactId) return;
        const contact = State.contacts.find(c => c.id === State.currentContactId);
        if (!contact) return;
        this.classList.toggle('active');
        contact.isPinned = this.classList.contains('active');
        Storage.saveContacts(State.contacts);
        initChatList();
        showToast(contact.isPinned ? '已置顶' : '已取消置顶');
    });

    document.getElementById('chat-bg-cell')?.addEventListener('click', () => {
        if (!State.currentContactId) return;
        const contact = State.contacts.find(c => c.id === State.currentContactId);
        if (!contact) return;
        openChatBgPage(contact);
    });

    document.getElementById('chat-memory-cell')?.addEventListener('click', () => {
        if (!State.currentContactId) return;
        const contact = State.contacts.find(c => c.id === State.currentContactId);
        if (!contact) return;
        openTargetMemoryView(contact);
    });
    document.getElementById('group-chat-memory-cell')?.addEventListener('click', () => {
        const session = getCurrentSession();
        if (!isGroupSession(session)) return;
        openTargetMemoryView(session);
    });

    let promptHistoryCategory = 'chat';
    let promptHistorySelectedId = '';

    const renderPromptTraceHistory = (contactId, category = 'chat') => {
        const listEl = document.getElementById('prompt-history-list');
        const contentEl = document.getElementById('prompt-view-content');
        const emptyEl = document.getElementById('prompt-view-empty');
        const tokenEl = document.getElementById('prompt-view-token-badge');
        const metaEl = document.getElementById('prompt-history-meta');
        if (!listEl || !contentEl || !emptyEl || !metaEl) return;

        const entries = getPromptTraceEntries(contactId, category);
        listEl.innerHTML = '';
        if (!entries.length) {
            listEl.style.display = 'none';
            contentEl.textContent = '';
            contentEl.style.display = 'none';
            emptyEl.style.display = 'block';
            metaEl.textContent = '当前分类暂无记录';
            if (tokenEl) tokenEl.textContent = 'Tokens: -';
            promptHistorySelectedId = '';
            return;
        }

        emptyEl.style.display = 'none';
        listEl.style.display = 'flex';
        const selected = entries.find((item) => item.id === promptHistorySelectedId) || entries[0];
        promptHistorySelectedId = selected.id;
        entries.forEach((item) => {
            const row = document.createElement('div');
            row.className = `prompt-history-item${item.id === promptHistorySelectedId ? ' active' : ''}`;
            row.innerHTML = `
                <div class="prompt-history-title">${escapeHtml(item.label)}</div>
                <div class="prompt-history-time">${escapeHtml(formatMomentTime(item.at))}</div>
            `;
            row.addEventListener('click', () => {
                promptHistorySelectedId = item.id;
                renderPromptTraceHistory(contactId, category);
            });
            listEl.appendChild(row);
        });

        contentEl.style.display = 'block';
        contentEl.innerHTML = renderPromptTraceContentHtml(selected.content);
        contentEl.scrollTop = 0;
        metaEl.textContent = `${selected.label} · ${formatMomentTime(selected.at)}`;
        if (tokenEl) tokenEl.textContent = `≈${estimateTokens(selected.content)} tokens`;
    };

    document.getElementById('chat-prompt-view-cell')?.addEventListener('click', () => {
        if (!State.currentContactId) return;
        const contact = State.contacts.find(c => c.id === State.currentContactId);
        if (!contact) return;
        promptHistoryCategory = 'chat';
        promptHistorySelectedId = '';
        openTargetPromptView(contact, 'chat', renderPromptTraceHistory);
    });
    document.getElementById('group-chat-prompt-view-cell')?.addEventListener('click', () => {
        const session = getCurrentSession();
        if (!isGroupSession(session)) return;
        promptHistoryCategory = 'chat';
        promptHistorySelectedId = '';
        openTargetPromptView(session, 'chat', renderPromptTraceHistory);
    });

    document.querySelectorAll('#prompt-view-category-tabs .prompt-history-tab').forEach((btn) => {
        btn.addEventListener('click', () => {
            const target = getPageTarget('prompt-view-page');
            if (!target?.id) return;
            promptHistoryCategory = String(btn.dataset.historyCategory || 'chat');
            promptHistorySelectedId = '';
            document.querySelectorAll('#prompt-view-category-tabs .prompt-history-tab').forEach((item) => {
                item.classList.toggle('active', item === btn);
            });
            renderPromptTraceHistory(String(target.id || ''), promptHistoryCategory);
        });
    });

    document.addEventListener('prompt-trace-updated', (event) => {
        const detail = event?.detail || {};
        const target = getPageTarget('prompt-view-page');
        if (!target?.id) return;
        if (String(detail.contactId || '') !== String(target.id || '')) return;
        if (String(detail.category || 'chat') !== String(promptHistoryCategory || 'chat')) return;
        renderPromptTraceHistory(String(target.id || ''), promptHistoryCategory);
    });

    document.getElementById('prompt-view-back-btn')?.addEventListener('click', () => {
        hidePage('prompt-view-page');
    });

    document.getElementById('memory-view-back-btn')?.addEventListener('click', () => {
        hidePage('memory-view-page');
    });

    document.getElementById('memory-vectorize-btn')?.addEventListener('click', () => {
        const target = getPageTarget('memory-view-page');
        if (!target?.id) {
            showToast('请先进入某个聊天');
            return;
        }
        vectorizeSummariesForContact(target).catch((err) => {
            showToast(`向量化失败：${formatVectorError(err)}`);
        });
    });
    document.getElementById('memory-manual-mega-btn')?.addEventListener('click', () => {
        const target = getPageTarget('memory-view-page');
        if (!target?.id) {
            showToast('请先进入某个聊天');
            return;
        }
        const count = document.getElementById('memory-manual-mega-count')?.value || '';
        triggerManualMegaSummary(target, count);
    });
    document.getElementById('chat-bg-back-btn')?.addEventListener('click', () => {
        hidePage('chat-bg-page');
    });
    document.getElementById('chat-bg-reset-cell')?.addEventListener('click', () => {
        const target = getChatBackgroundEditorTarget();
        if (!target) return;
        target.chatBackground = { type: 'default', value: '' };
        persistChatBackgroundTarget(target);
        applyChatBackground(target);
        renderChatBgGrid(target);
        showToast('已恢复默认');
    });
    const openChatBgPicker = async () => {
        const target = getChatBackgroundEditorTarget();
        if (!target) return;
        const current = target?.chatBackground?.type === 'image' ? getEditableStoredImageValue(target.chatBackground.value || '') : '';
        const result = await WeChatUI.showImagePicker('更换聊天背景', '输入背景图片URL（http(s):// 或 base64）', current, { storeLocalAssets: true, storagePrefix: 'chat_bg' });
        if (!result?.value) return;
        const val = cloneStoredImageValue(result.value || '');
        if (!hasStoredImageValue(val)) return;
        target.chatBackground = { type: 'image', value: val };
        persistChatBackgroundTarget(target);
        applyChatBackground(target);
        renderChatBgGrid(target);
        showToast('已设置');
    };
    document.getElementById('chat-bg-picker-cell')?.addEventListener('click', openChatBgPicker);

    document.getElementById('chat-clear-history-cell')?.addEventListener('click', async () => {
        if (!State.currentContactId) return;
        const contact = State.contacts.find(c => c.id === State.currentContactId);
        if (!contact) return;
        const ok = await WeChatUI.showConfirm('清空聊天记录', '确定清空聊天记录吗？清空后不可恢复。', '清空', '取消', true);
        if (!ok) return;
        State.chatHistories[contact.id] = [];
        contact.lastMessage = '';
        contact.lastTime = '';
        contact.lastActiveAt = 0;
        Storage.saveChatHistories(State.chatHistories);
        Storage.saveContacts(State.contacts);
        renderChatMessages();
        initChatList();
        showToast('已清空');
    });

    // 发送消息
    const sendBtn = document.getElementById('send-message-btn');
    const input = document.getElementById('message-input');
    const chatModelSwitchBtn = document.getElementById('chat-model-switch-btn');
    const chatModelDropdown = document.getElementById('chat-model-dropdown');
    const plusBtn = document.getElementById('chat-plus-btn');

    const sendMessage = async () => {
        if (sendMessage._busy) return;
        const text = input.value.trim();
        const session = getCurrentSession();
        if (!text || !session) return;
        const contact = getCurrentPrivateContact();
        const userProfile = getUserProfileForContact(contact);
        const isGroup = isGroupSession(session);
        const offlineConfig = (!isGroup && contact) ? getOfflineModeConfig(contact) : DEFAULT_OFFLINE_MODE_CONFIG;
        const groupOfflineConfig = isGroup ? getGroupOfflineModeConfig(session) : DEFAULT_OFFLINE_MODE_CONFIG;
        sendMessage._busy = true;

        try {
            let lastMessagePreview = text;
            const replyDraft = window.getReplyDraft?.();
            const shouldUseGroupOfflineComposer = isGroup
                && groupOfflineConfig.enabled
                && !(replyDraft && replyDraft.quote)
                && hasOfflineComposerSyntax(text);
            if (!State.chatHistories[session.id]) {
                State.chatHistories[session.id] = [];
            }
            const nowTs = Date.now();
            let outgoingEntries = [];
            if ((offlineConfig.enabled && contact && !(replyDraft && replyDraft.quote)) || shouldUseGroupOfflineComposer) {
                const offlineItems = parseOfflineComposerInput(text);
                if (offlineItems.length > 0) {
                    lastMessagePreview = summarizeOfflineComposerItems(offlineItems);
                    outgoingEntries = offlineItems.map((item, idx) => ({
                        role: 'user',
                        content: JSON.stringify(item),
                        time: nowTs + idx
                    }));
                }
            }
            if (outgoingEntries.length === 0) {
                let messageContent = text;
                if (replyDraft && replyDraft.quote) {
                    messageContent = JSON.stringify({
                        type: 'quote',
                        quote: replyDraft.quote,
                        content: text
                    });
                    lastMessagePreview = `[引用] ${text}`;
                }
                outgoingEntries = [{
                    role: 'user',
                    content: messageContent,
                    time: nowTs
                }];
            }

            outgoingEntries.forEach((entry) => {
                State.chatHistories[session.id].push(entry);
            });
            input.value = '';
            if (String(input?.tagName || '').toUpperCase() === 'TEXTAREA') {
                input.style.height = '';
            }
            window.clearReplyDraft?.();
            hideChatAtPanel();

            sendBtn.style.display = 'none';
            plusBtn.style.display = 'flex';

            if (contact) {
                contact.lastMessage = lastMessagePreview;
                const now = new Date();
                contact.lastTime = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
                contact.lastActiveAt = nowTs;
                refreshAutoMessageScheduleFromActivity(contact, nowTs);
            }
            updateSessionPreview(session.id, lastMessagePreview, nowTs);

            Storage.saveChatHistories(State.chatHistories);
            if (contact) Storage.saveContacts(State.contacts);
            renderChatMessages();
            initChatList();
            renderGroupSessionsList();

            maybeQueueAutoSummaryForTarget(contact || session);
        } finally {
            sendMessage._busy = false;
        }
    };

    sendBtn?.addEventListener('click', sendMessage);
    const autoResizeChatInput = () => {
        if (!input || String(input.tagName || '').toUpperCase() !== 'TEXTAREA') return;
        input.style.height = 'auto';
        const maxH = 140;
        const nextH = Math.max(40, Math.min(maxH, input.scrollHeight || 40));
        input.style.height = `${nextH}px`;
        input.style.overflowY = (input.scrollHeight || 0) > maxH ? 'auto' : 'hidden';
    };
    autoResizeChatInput();
    input?.addEventListener('keydown', (e) => {
        if (e.key !== 'Enter') return;
        if (e.ctrlKey || e.metaKey) {
            e.preventDefault();
            sendMessage();
        }
    });
    chatModelSwitchBtn?.addEventListener('click', () => {
        if (plusPanel) plusPanel.classList.remove('show');
        if (stickerPanel) stickerPanel.classList.remove('show');
        toggleChatModelDropdown();
    });
    chatModelDropdown?.addEventListener('mousedown', (e) => {
        e.stopPropagation();
    });
    updateChatModelSwitchButton();

    // 输入框变化显示/隐藏发送按钮
    const stickerBtn = document.querySelector('.input-icon svg circle[cx="15.5"]')?.closest('button');
    const stickerPanel = document.getElementById('chat-sticker-panel');
    const atPanel = document.getElementById('chat-at-panel');

    input?.addEventListener('input', () => {
        autoResizeChatInput();
        if (input.value.trim()) {
            sendBtn.style.display = 'block';
            plusBtn.style.display = 'none';
        } else {
            sendBtn.style.display = 'none';
            plusBtn.style.display = 'flex';
        }
        const session = getCurrentSession();
        const mention = getChatMentionQuery(input.value, input.selectionStart);
        if (isGroupSession(session) && mention) renderChatAtPanel(mention.keyword);
        else hideChatAtPanel();
    });
    input?.addEventListener('click', () => {
        const session = getCurrentSession();
        const mention = getChatMentionQuery(input.value, input.selectionStart);
        if (isGroupSession(session) && mention) renderChatAtPanel(mention.keyword);
    });
    atPanel?.addEventListener('mousedown', (e) => {
        e.stopPropagation();
    });

    // 表情面板控制
    if (stickerBtn) {
        stickerBtn.addEventListener('mousedown', (e) => {
            e.preventDefault();
            e.stopPropagation();
            if (stickerPanel) {
                if (stickerPanel.classList.contains('show')) {
                    stickerPanel.classList.remove('show');
                } else {
                    stickerPanel.classList.add('show');
                    if (plusPanel) plusPanel.classList.remove('show');
                    initChatStickerPanel();
                    setTimeout(scrollToBottom, 50);
                }
            }
        });
    }

    // 加号菜单控制
    const plusPanel = document.getElementById('chat-plus-panel');
    const plusPagesTrack = document.getElementById('chat-plus-pages-track');
    const plusPagination = document.getElementById('chat-plus-pagination');
    const plusSourceGrid = document.getElementById('chat-plus-grid');
    const PLUS_PAGE_SIZE = 8;
    let plusPageCount = 1;
    let activePlusPage = 0;
    let plusPageWheelLocked = false;
    let plusDragPointerId = null;
    let plusDragStartX = 0;
    let plusDragDeltaX = 0;
    let plusDragMoved = false;
    let plusDragSuppressClickUntil = 0;

    const setPlusTrackTranslate = (translatePct, options = {}) => {
        if (!plusPagesTrack) return;
        plusPagesTrack.style.transition = options.immediate ? 'none' : 'transform 0.28s cubic-bezier(0.22, 1, 0.36, 1)';
        plusPagesTrack.style.transform = `translate3d(${translatePct}%, 0, 0)`;
    };

    const setPlusPanelPage = (pageIndex, options = {}) => {
        if (!plusPagesTrack) return;
        const maxPage = Math.max(0, plusPageCount - 1);
        activePlusPage = Math.max(0, Math.min(maxPage, parseInt(pageIndex, 10) || 0));
        setPlusTrackTranslate(-(activePlusPage * 100), { immediate: options.immediate === true });
        plusPagination?.querySelectorAll('.plus-page-dot').forEach((dot, idx) => {
            dot.classList.toggle('active', idx === activePlusPage);
            dot.setAttribute('aria-current', idx === activePlusPage ? 'page' : 'false');
        });
    };

    const initPlusPanelPagination = () => {
        if (!plusPagesTrack || !plusSourceGrid) return;
        const items = Array.from(plusSourceGrid.children).filter((el) => el.classList?.contains('plus-item'));
        if (!items.length) return;
        plusPagesTrack.innerHTML = '';
        plusPageCount = Math.max(1, Math.ceil(items.length / PLUS_PAGE_SIZE));
        for (let i = 0; i < plusPageCount; i += 1) {
            const page = document.createElement('div');
            page.className = 'plus-page';
            const grid = document.createElement('div');
            grid.className = 'plus-grid';
            items.slice(i * PLUS_PAGE_SIZE, (i + 1) * PLUS_PAGE_SIZE).forEach((item) => {
                grid.appendChild(item);
            });
            page.appendChild(grid);
            plusPagesTrack.appendChild(page);
        }
        if (plusPagination) {
            plusPagination.innerHTML = '';
            for (let i = 0; i < plusPageCount; i += 1) {
                const dot = document.createElement('button');
                dot.type = 'button';
                dot.className = 'plus-page-dot';
                dot.setAttribute('aria-label', `第 ${i + 1} 页`);
                dot.addEventListener('click', (e) => {
                    e.stopPropagation();
                    setPlusPanelPage(i);
                });
                plusPagination.appendChild(dot);
            }
            plusPagination.style.display = plusPageCount > 1 ? 'flex' : 'none';
        }
        setPlusPanelPage(0, { immediate: true });
    };

    initPlusPanelPagination();
    
    // 使用 mousedown 可以在 blur/click 之前拦截到，避免手机端点击冲突
    if (plusBtn) {
        plusBtn.addEventListener('mousedown', (e) => {
            e.preventDefault();
            e.stopPropagation();
            if (plusPanel) {
                if (plusPanel.classList.contains('show')) {
                    plusPanel.classList.remove('show');
                } else {
                    setPlusPanelPage(0, { immediate: true });
                    plusPanel.classList.add('show');
                    if (stickerPanel) stickerPanel.classList.remove('show');
                    setTimeout(scrollToBottom, 50);
                }
            }
        });
    }

    // 点击全局区域隐藏面板
    document.addEventListener('mousedown', (e) => {
        if (plusPanel && plusPanel.classList.contains('show')) {
            if (!e.target.closest('#chat-plus-panel')) {
                plusPanel.classList.remove('show');
            }
        }
        if (stickerPanel && stickerPanel.classList.contains('show')) {
            if (!e.target.closest('#chat-sticker-panel')) {
                stickerPanel.classList.remove('show');
            }
        }
        if (isChatModelDropdownOpen()) {
            if (!e.target.closest('#chat-model-dropdown') && !e.target.closest('#chat-model-switch-btn')) {
                closeChatModelDropdown();
            }
        }
        if (isAiReplyDropdownOpen()) {
            if (!e.target.closest('#ai-reply-dropdown') && !e.target.closest('#call-ai-reply-btn')) {
                closeAiReplyDropdown();
            }
        }
        if (atPanel && atPanel.style.display !== 'none') {
            if (!e.target.closest('#chat-at-panel') && !e.target.closest('#message-input')) {
                hideChatAtPanel();
            }
        }
    });

    plusPanel?.addEventListener('mousedown', (e) => {
        e.stopPropagation();
    });

    plusPanel?.addEventListener('click', (e) => {
        if (Date.now() < plusDragSuppressClickUntil) {
            e.preventDefault();
            e.stopPropagation();
        }
    }, true);

    plusPagesTrack?.addEventListener('pointerdown', (e) => {
        if (plusPageCount <= 1) return;
        if (typeof e.button === 'number' && e.button !== 0) return;
        plusDragPointerId = e.pointerId;
        plusDragStartX = e.clientX;
        plusDragDeltaX = 0;
        plusDragMoved = false;
    });

    plusPagesTrack?.addEventListener('pointermove', (e) => {
        if (plusDragPointerId !== e.pointerId || !plusPanel) return;
        plusDragDeltaX = e.clientX - plusDragStartX;
        if (!plusDragMoved && Math.abs(plusDragDeltaX) < 8) return;
        if (!plusDragMoved) {
            plusDragMoved = true;
            plusPagesTrack.classList.add('dragging');
            plusPagesTrack.setPointerCapture?.(e.pointerId);
        }
        const panelWidth = Math.max(plusPanel.clientWidth, 1);
        let deltaPct = (plusDragDeltaX / panelWidth) * 100;
        if ((activePlusPage === 0 && deltaPct > 0) || (activePlusPage === plusPageCount - 1 && deltaPct < 0)) {
            deltaPct *= 0.35;
        }
        setPlusTrackTranslate(-(activePlusPage * 100) + deltaPct, { immediate: true });
    });

    const finishPlusDrag = (e) => {
        if (plusDragPointerId === null) return;
        if (e && plusDragPointerId !== e.pointerId) return;
        const moved = plusDragMoved;
        const deltaX = plusDragDeltaX;
        const threshold = plusPanel ? Math.min(72, plusPanel.clientWidth * 0.18) : 56;
        plusPagesTrack?.classList.remove('dragging');
        if (moved && Math.abs(deltaX) > threshold) {
            setPlusPanelPage(activePlusPage + (deltaX < 0 ? 1 : -1));
            plusDragSuppressClickUntil = Date.now() + 260;
        } else {
            setPlusPanelPage(activePlusPage);
        }
        if (moved) plusPagesTrack?.releasePointerCapture?.(plusDragPointerId);
        plusDragPointerId = null;
        plusDragStartX = 0;
        plusDragDeltaX = 0;
        plusDragMoved = false;
    };

    plusPagesTrack?.addEventListener('pointerup', finishPlusDrag);
    plusPagesTrack?.addEventListener('pointercancel', finishPlusDrag);

    plusPanel?.addEventListener('wheel', (e) => {
        if (plusPageCount <= 1 || plusPageWheelLocked) return;
        const delta = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
        if (Math.abs(delta) < 10) return;
        e.preventDefault();
        e.stopPropagation();
        plusPageWheelLocked = true;
        setPlusPanelPage(activePlusPage + (delta > 0 ? 1 : -1));
        setTimeout(() => {
            plusPageWheelLocked = false;
        }, 180);
    }, { passive: false });

