// ===================================
// 记忆查看功能
// ==========================

function loadMemoryView(target) {
    if (!target?.id) return;
    setPageTarget('memory-view-page', target);
    updateMemoryViewTitle(target);
    const summaryStore = ensureSummaryStore(target.id);
    const megaList = [...summaryStore.mega].reverse();
    const pendingMiniList = [...summaryStore.mini].filter((item) => !String(item?.mergedMegaId || '').trim()).reverse();
    const mergedMiniList = [...summaryStore.mini].filter((item) => String(item?.mergedMegaId || '').trim()).reverse();
    const pendingMini = getPendingMiniSummaries(target.id);
    const vectorStore = State.summaryVectors?.[target.id];
    const rawVectorEntries = vectorStore?.items && typeof vectorStore.items === 'object'
        ? Object.entries(vectorStore.items)
        : [];
    const summaryById = new Map([...summaryStore.mega, ...summaryStore.mini].map((item) => [String(item?.id || '').trim(), item]));
    const formatEmbeddingPreview = (embedding, size = 8) => {
        const list = Array.isArray(embedding) ? embedding.slice(0, size) : [];
        if (list.length === 0) return '';
        return list.map((n) => {
            const num = Number(n);
            if (!Number.isFinite(num)) return '0';
            return Math.abs(num) >= 1 ? num.toFixed(3) : num.toFixed(4);
        }).join(', ');
    };
    const vectorGroupsMap = new Map();
    rawVectorEntries.forEach(([vectorId, item]) => {
        const parentId = String(item?.parentId || '').trim() || String(vectorId || '').split('#')[0];
        if (!parentId) return;
        if (!vectorGroupsMap.has(parentId)) {
            const sourceItem = summaryById.get(parentId);
            const kind = String(sourceItem?.kind || (parentId.startsWith('mega_') ? 'mega' : 'mini')).trim();
            vectorGroupsMap.set(parentId, {
                parentId,
                kind,
                sourceItem,
                time: Number(item?.time || sourceItem?.time || 0) || 0,
                messageCount: Number(item?.messageCount || sourceItem?.messageCount || 0) || 0,
                summaryCount: Number(sourceItem?.summaryCount || (sourceItem?.sourceSummaryIds || []).length || 0) || 0,
                chunks: []
            });
        }
        const group = vectorGroupsMap.get(parentId);
        group.chunks.push({
            id: String(vectorId || '').trim(),
            index: Math.max(0, parseInt(String(vectorId || '').split('#')[1] || '0', 10) || 0),
            text: String(item?.text || '').trim(),
            embedding: Array.isArray(item?.embedding) ? item.embedding : []
        });
    });
    const vectorGroups = Array.from(vectorGroupsMap.values())
        .map((group) => ({
            ...group,
            chunks: group.chunks.sort((a, b) => a.index - b.index)
        }))
        .sort((a, b) => b.time - a.time);

    const megaContainer = document.getElementById('memory-mega-list-container');
    const miniContainer = document.getElementById('memory-mini-list-container');
    const fallbackContainer = document.getElementById('memory-list-container');
    const emptyHint = document.getElementById('memory-empty-hint');
    const pendingCountEl = document.getElementById('memory-pending-mini-count');
    const megaCountInput = document.getElementById('memory-manual-mega-count');
    const megaHintEl = document.getElementById('memory-manual-mega-hint');
    if (!megaContainer || !miniContainer || !fallbackContainer || !emptyHint) return;

    if (pendingCountEl) pendingCountEl.textContent = `待合并 ${pendingMini.length} 条小总结`;
    if (megaCountInput) {
        megaCountInput.max = String(Math.max(1, pendingMini.length));
        if (!megaCountInput.value || Number(megaCountInput.value) > pendingMini.length) {
            megaCountInput.value = pendingMini.length > 0
                ? String(Math.min(pendingMini.length, Math.max(1, parseInt(State.summaryConfig?.megaTriggerCount ?? 10, 10) || 10)))
                : '';
        }
    }
    if (megaHintEl) {
        megaHintEl.textContent = pendingMini.length > 0
            ? `当前有 ${pendingMini.length} 条尚未并入大总结的小总结；会在当前页直接处理，不跳去聊天页。`
            : '当前还没有待合并的小总结。';
    }

    if (megaList.length === 0 && pendingMiniList.length === 0 && mergedMiniList.length === 0 && vectorGroups.length === 0) {
        megaContainer.innerHTML = '';
        miniContainer.innerHTML = '';
        fallbackContainer.innerHTML = '';
        emptyHint.style.display = 'block';
        return;
    }

    emptyHint.style.display = 'none';
    fallbackContainer.innerHTML = '';

    const renderCard = (item, index, total, kind) => {
        const date = new Date(item.time);
        const dateStr = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')} ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
        const isLatestMega = kind === 'mega' && index === 0;
        const canDeleteMini = kind === 'mini' && !String(item.mergedMegaId || '').trim();
        const showDelete = (kind === 'mega' && isLatestMega) || canDeleteMini;
        const showRedo = kind === 'mini' || (kind === 'mega' && isLatestMega);
        const title = kind === 'mega' ? `大总结 ${total - index}` : `小总结 ${total - index}`;
        const metaText = kind === 'mega'
            ? `吸收 ${item.summaryCount || (item.sourceSummaryIds || []).length || 0} 条小总结`
            : `${item.messageCount || 0} 条消息`;
        const statusText = kind === 'mini'
            ? (String(item.mergedMegaId || '').trim() ? '已并入大总结' : '待并入大总结')
            : (isLatestMega ? '当前最新大总结' : '历史大总结');
        return `
            <div class="memory-item" data-kind="${kind}" data-id="${escapeHtml(String(item.id || ''))}" style="margin: 12px; padding: 16px; background: #f7f7f7; border-radius: 8px; position: relative;">
                <div style="display: flex; justify-content: space-between; align-items: center; gap: 8px; margin-bottom: 12px;">
                    <div style="font-size: 13px; color: #888; line-height: 1.6;">
                        <span>${title}</span>
                        <span style="margin-left: 12px;">${dateStr}</span>
                        <span style="margin-left: 12px;">${metaText}</span>
                        <span style="margin-left: 12px; color: ${kind === 'mega' ? '#07c160' : '#576b95'};">${statusText}</span>
                    </div>
                    <div style="display:flex; align-items:center; gap:8px; flex-shrink:0;">
                        ${showRedo ? `<button class="memory-redo-btn" data-id="${escapeHtml(String(item.id || ''))}" style="padding: 4px 8px; font-size: 12px; border: 1px solid #07c160; background: transparent; color: #07c160; border-radius: 4px; cursor: pointer;">重做</button>` : ''}
                        ${showDelete ? `<button class="memory-delete-btn" data-kind="${kind}" data-id="${escapeHtml(String(item.id || ''))}" style="padding: 4px 8px; font-size: 12px; border: 1px solid #ff3b30; background: transparent; color: #ff3b30; border-radius: 4px; cursor: pointer;">删除</button>` : ''}
                    </div>
                </div>
                <div class="memory-content" style="white-space: pre-wrap; font-size: 14px; line-height: 1.6; color: #333;">${escapeHtml(item.content)}</div>
            </div>
        `;
    };

    megaContainer.innerHTML = `
        <div style="padding: 0 12px; font-size: 13px; color: #888;">大总结</div>
        ${megaList.length > 0 ? megaList.map((item, index) => renderCard(item, index, megaList.length, 'mega')).join('') : '<div style="padding: 18px 12px; color:#999; font-size:13px;">还没有大总结</div>'}
    `;
    miniContainer.innerHTML = `
        <div style="padding: 0 12px; font-size: 13px; color: #888;">小总结</div>
        ${pendingMiniList.length > 0 ? pendingMiniList.map((item, index) => renderCard(item, index, pendingMiniList.length, 'mini')).join('') : '<div style="padding: 18px 12px; color:#999; font-size:13px;">当前没有待并入大总结的小总结</div>'}
        ${mergedMiniList.length > 0 ? `
            <details style="margin: 12px; background: #fff; border-radius: 8px; border: 1px solid #e9e9e9;">
                <summary style="padding: 14px 16px; cursor: pointer; color: #576b95; font-size: 13px;">已折叠 ${mergedMiniList.length} 条已并入大总结的小总结</summary>
                <div style="padding-top: 4px; padding-bottom: 8px;">
                    ${mergedMiniList.map((item, index) => renderCard(item, index, mergedMiniList.length, 'mini')).join('')}
                </div>
            </details>
        ` : ''}
    `;
    fallbackContainer.innerHTML = `
        <details class="memory-vector-section">
            <summary class="memory-vector-section-summary">
                <div class="memory-vector-head">
                    <div>
                        <div class="memory-vector-title">已向量化内容</div>
                        <div class="memory-vector-subtitle">这里展示当前还能参与记忆检索的向量分块，不会把已经失效的旧版本一直堆着。</div>
                    </div>
                    <div class="memory-vector-stat">
                        <div>${vectorGroups.length} 条总结</div>
                        <div>${rawVectorEntries.length} 个分块</div>
                        <div>${vectorStore?.model ? `模型：${escapeHtml(String(vectorStore.model))}` : '还没记录模型'}</div>
                    </div>
                </div>
            </summary>
            <div class="memory-vector-section-body">
            ${vectorGroups.length > 0 ? vectorGroups.map((group) => {
                const date = group.time ? new Date(group.time) : null;
                const dateStr = date
                    ? `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')} ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`
                    : '时间未知';
                const title = group.kind === 'mega' ? '大总结向量' : '小总结向量';
                const meta = group.kind === 'mega'
                    ? `吸收 ${group.summaryCount || 0} 条小总结`
                    : `${group.messageCount || 0} 条消息`;
                return `
                    <details class="memory-vector-card">
                        <summary class="memory-vector-card-summary">
                            <div>
                                <div class="memory-vector-card-title">${title}</div>
                                <div class="memory-vector-card-meta">${dateStr} · ${meta} · ${group.chunks.length} 个分块</div>
                            </div>
                            <span class="memory-vector-card-tag">${group.kind === 'mega' ? '长期记忆' : '阶段记忆'}</span>
                        </summary>
                        <div class="memory-vector-card-body">
                            ${group.chunks.map((chunk, chunkIndex) => {
                                const dimension = Array.isArray(chunk.embedding) ? chunk.embedding.length : 0;
                                const preview = formatEmbeddingPreview(chunk.embedding);
                                return `
                                    <div class="memory-vector-chunk">
                                        <div class="memory-vector-chunk-head">
                                            <span>分块 ${chunkIndex + 1}/${group.chunks.length}</span>
                                            <span>${dimension || '?'} 维</span>
                                        </div>
                                        <div class="memory-vector-chunk-text">${escapeHtml(chunk.text || '')}</div>
                                        ${preview ? `<div class="memory-vector-chunk-embedding">向量预览：${escapeHtml(preview)}${dimension > 8 ? ' ...' : ''}</div>` : ''}
                                    </div>
                                `;
                            }).join('')}
                        </div>
                    </details>
                `;
            }).join('') : '<div class="memory-vector-empty">还没有向量数据，点右上角“向量化”后，这里就会显示当前实际入库的内容。</div>'}
            </div>
        </details>
    `;

    [megaContainer, miniContainer].forEach((container) => {
        container.querySelectorAll('.memory-redo-btn').forEach((btn) => {
            btn.addEventListener('click', async (e) => {
                e.stopPropagation();
                const itemId = String(btn.dataset.id || '').trim();
                if (!itemId) return;
                const card = btn.closest('.memory-item');
                const kind = String(card?.dataset.kind || '').trim();
                if (kind === 'mega') {
                    await redoMegaSummary(target, itemId);
                } else {
                    await redoMiniSummary(target, itemId);
                }
            });
        });
        container.querySelectorAll('.memory-delete-btn').forEach((btn) => {
            btn.addEventListener('click', async (e) => {
                e.stopPropagation();
                const kind = String(btn.dataset.kind || '').trim();
                const itemId = String(btn.dataset.id || '').trim();
                if (!itemId) return;
                if (kind === 'mega') {
                    await deleteMegaSummary(target.id, itemId);
                    return;
                }
                const store = ensureSummaryStore(target.id);
                const idx = store.mini.findIndex((item) => String(item?.id || '') === itemId);
                if (idx < 0) return;
                const summaryItem = store.mini[idx];
                if (String(summaryItem?.mergedMegaId || '').trim()) {
                    await WeChatUI.showAlert('暂不支持', '这条小总结已经并入大总结，请先删除最新那条大总结后再处理。');
                    return;
                }
                const ok = await WeChatUI.showConfirm('删除小总结', '确定删除这条小总结吗？', '删除', '取消', true);
                if (!ok) return;
                store.mini.splice(idx, 1);
                Storage.saveSummaryHistories(State.summaryHistories);
                removeSummaryVectorsByItems(target.id, [summaryItem]);
                loadMemoryView(target);
                showToast('小总结已删除');
            });
        });
    });
}

// 为所有提示词添加重置按钮的样式和功能已在总结设置中实现
