document.addEventListener('DOMContentLoaded', () => {
    // 延迟初始化，确保其他代码已加载
    setTimeout(() => {
        initContextMenuEvents();
        console.log('消息长按菜单已初始化');
    }, CONSTANTS.TIMING.INIT_DELAY);
});

